@tailwind base;
@tailwind components;
@tailwind utilities;

/* Set default font for body */
body {
  font-family: 'Gilroy-Light', sans-serif;
}

/* Authentic Gempad Fonts */
@font-face {
  font-family: 'Gilroy-Light';
  src: url('/Gilroy-Light.otf') format('opentype');
  font-display: swap;
  font-weight: 300;
}

@font-face {
  font-family: 'Gilroy-ExtraBold';
  src: url('/Gilroy-ExtraBold.otf') format('opentype');
  font-display: swap;
  font-weight: 800;
}

@font-face {
  font-family: 'NeueMachina-Regular';
  src: url('/NeueMachina-Regular.otf') format('opentype');
  font-display: swap;
  font-weight: 400;
}

/* Custom animations for Featured Projects Carousel */
@keyframes slideInUp {
  0% {
    opacity: 0;
    transform: translateY(30px) scale(0.95);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes slideInLeft {
  0% {
    opacity: 0;
    transform: translateX(-30px);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInRight {
  0% {
    opacity: 0;
    transform: translateX(30px);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes glow {
  0%, 100% {
    box-shadow: 0 0 20px rgba(34, 205, 166, 0.3);
  }
  50% {
    box-shadow: 0 0 40px rgba(34, 205, 166, 0.6);
  }
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.carousel-card {
  background: linear-gradient(
    90deg,
    transparent,
    rgba(34, 205, 166, 0.1),
    transparent
  );
  background-size: 200% 100%;
