}

:root {
  /* Exact Gemlaunch colors - fixed implementation */
  --gem-background: #0a0f0c;        /* Page background */
  --gem-sidebar: #0f1713;           /* Sidebar background */
  --gem-card: #253935;              /* Main card/form background */
  --gem-card-hover: #2a4f3f;        /* Card hover state */
  --gem-form-bg: #253935;           /* Form container background */
  --gem-input-bg: #0f1713;          /* Input field backgrounds */
  --gem-primary: #22cda6;           /* Primary button/accent color */
  --gem-primary-hover: #1bb6b4;     /* Primary hover state */
  --gem-accent: #22cda6;            /* Accent color */
  --gem-text: #ffffff;              /* Primary text */
  --gem-text-muted: #ffffff;        /* Muted text */
  --gem-text-secondary: #ffffff;    /* Secondary text */
  --gem-border: #3d5c4d;            /* Border color */
  --gem-border-light: #4a6a57;      /* Light border variant */
  --gem-success: #22cda6;           /* Success color */
  --gem-warning: #f59e0b;           /* Warning color */
  --gem-error: #ef4444;             /* Error color */

  --background: var(--gem-background);
  --foreground: var(--gem-text);
  --muted: var(--gem-card);
  --muted-foreground: var(--gem-text);
  --popover: var(--gem-background);
  --popover-foreground: var(--gem-text);
  --card: var(--gem-card);
  --card-foreground: var(--gem-text);
  --border: var(--gem-border);
  --input: var(--gem-input-bg);
  --primary: var(--gem-primary);
  --primary-foreground: var(--gem-background);
  --secondary: var(--gem-card);
  --secondary-foreground: var(--gem-text);
  --accent: var(--gem-card-hover);
  --accent-foreground: var(--gem-text);
  --destructive: var(--gem-error);
  --destructive-foreground: var(--gem-text);
  --ring: var(--gem-primary);
  --radius: 0.5rem;

  /* Sidebar colors */
  --sidebar-background: #0f1713;
  --sidebar-foreground: var(--gem-text);
  --sidebar-primary: var(--gem-primary);
  --sidebar-primary-foreground: var(--gem-sidebar);
  --sidebar-accent: var(--gem-primary);
