  --chart-4: var(--gem-warning);
  --chart-5: #8b5cf6;
}

::-webkit-scrollbar {
  width: 12px;
}

::-webkit-scrollbar-thumb {
  height: 4rem;
  /* border-radius: 0.5rem; */
  border: 4px solid transparent;
  background-clip: content-box;
  background-color: #22CDA6;
}

/* Horizontal scrollbar for tables */
.table-container::-webkit-scrollbar {
  height: 2px;
  background-color: transparent;
}

.table-container::-webkit-scrollbar-thumb {
  border-radius: 10px;
  background: linear-gradient(90deg, rgba(255,255,255,0) 2%, #22CDA660 50%, rgba(255,255,255,0) 98%);
}

.table-container::-webkit-scrollbar-track {
  border-radius: 10px;
  background: transparent;
}

/* Override all shadcn components with Gemlaunch styling */
@layer base {
  * {
    border-color: var(--gem-border);
  }

  body {
    background-color: var(--gem-background) !important;
    color: var(--gem-text) !important;
  }

  /* Force all inputs to use Gemlaunch styling */
  input[type="text"], 
  input[type="email"], 
  input[type="password"], 
  input[type="number"], 
  textarea,
  select {
    background-color: var(--gem-input-bg) !important;
    border: 1px solid var(--gem-border) !important;
    color: var(--gem-text) !important;
    border-radius: 8px !important;
  }

  input:focus, 
  textarea:focus, 
  select:focus {
    border-color: var(--gem-primary) !important;
    box-shadow: 0 0 0 2px rgba(38, 208, 206, 0.2) !important;
    outline: none !important;
  }

  /* Force all buttons to use Gemlaunch styling */
  button[data-variant="default"],
  .bg-primary {
    background-color: var(--gem-primary) !important;
    color: #000000 !important;
    border: none !important;
  }

  button[data-variant="default"]:hover,
  .bg-primary:hover {
    background-color: var(--gem-primary-hover) !important;
  }

  /* Card styling */
  .bg-card,
  [data-shadcn="card"] {
    background-color: var(--gem-card) !important;
    border: 1px solid var(--gem-border) !important;
  }
}

/* Custom Gemlaunch styling */
@layer components {
  .gem-form-container {
    background: var(--gem-form-bg) !important;
    border: 1px solid var(--gem-border);
    border-radius: 12px;
    padding: 32px;
    max-width: 600px;
    margin: 0 auto;
  }

  .gem-card {
    background: var(--gem-card);
    border: 1px solid var(--gem-border);
    border-radius: 8px;
    transition: all 0.2s ease;
  }

  .gem-card:hover {
    border-color: var(--gem-border-light);
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
  }
}

.dark {
  --background: hsl(240, 10%, 3.9%);
  --foreground: hsl(0, 0%, 98%);
  --muted: hsl(240, 3.7%, 15.9%);
  --muted-foreground: hsl(240, 5%, 64.9%);
