  }

  .leaderboard-glow {
    box-shadow: 0 0 20px hsla(188, 95%, 42%, 0.3);
  }

  .pulse-glow {
    animation: pulse-glow 2s infinite;
  }

  @keyframes pulse-glow {
    0%, 100% { 
      box-shadow: 0 0 20px hsla(188, 95%, 42%, 0.3); 
    }
