              >
                <item.icon className={`h-4 w-4 ${!sidebarExpanded ? 'mx-auto' : 'mr-3'}`} />
                {sidebarExpanded && (
                  <>
                    <span className="text-sm font-medium flex-1 font-gilroy-light">{item.label}</span>
                    {item.hasDropdown && (
