import { useState, useRef } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { 
  User, 
  Camera, 
  Plus, 
  Trash2, 
  Star, 
  Link, 
  Twitter, 
  MessageCircle,
  Users,
  Globe,
  Shield,
  Wallet,
  Copy,
  Check
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { web3Service } from "@/lib/web3";

export default function Profile() {
  const [isEditing, setIsEditing] = useState(false);
  const [newWalletLabel, setNewWalletLabel] = useState("");
  const [newWalletAddress, setNewWalletAddress] = useState("");
  const [copied, setCopied] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const connectedWallet = web3Service.getAccount();

  // Fetch user profile data
  const { data: profile, isLoading } = useQuery({
    queryKey: ["/api/profile", connectedWallet],
    queryFn: () => {
      if (!connectedWallet) return Promise.resolve(null);
      return fetch(`/api/profile/${connectedWallet}`).then(res => res.json());
    },
    enabled: !!connectedWallet,
  });

  // Fetch user wallets
  const { data: userWallets } = useQuery({
    queryKey: ["/api/profile/wallets", connectedWallet],
    queryFn: () => {
      if (!connectedWallet) return Promise.resolve([]);
      return fetch(`/api/profile/wallets/${connectedWallet}`).then(res => res.json());
    },
    enabled: !!connectedWallet,
  });

  // Update profile mutation
  const updateProfileMutation = useMutation({
    mutationFn: async (profileData: any) => {
      const response = await apiRequest("PUT", `/api/profile/${connectedWallet}`, profileData);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/profile"] });
      setIsEditing(false);
      toast({
        title: "Profile Updated",
        description: "Your profile has been successfully updated.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update profile.",
        variant: "destructive",
      });
    },
  });

  // Add wallet mutation
  const addWalletMutation = useMutation({
    mutationFn: async (walletData: { address: string; label: string }) => {
      const response = await apiRequest("POST", `/api/profile/wallets/${connectedWallet}`, walletData);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/profile/wallets"] });
      setNewWalletAddress("");
      setNewWalletLabel("");
      toast({
        title: "Wallet Added",
        description: "New wallet has been added to your account.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to add wallet.",
        variant: "destructive",
      });
    },
  });

  // Compress image and convert to base64
  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d')!;
      const img = new Image();

      img.onload = () => {
        // Set canvas size (max 200x200)
        const maxSize = 200;
        let { width, height } = img;

        if (width > height) {
          if (width > maxSize) {
            height = (height * maxSize) / width;
            width = maxSize;
          }
        } else {
          if (height > maxSize) {
            width = (width * maxSize) / height;
            height = maxSize;
          }
        }

        canvas.width = width;
        canvas.height = height;

        // Draw and compress
        ctx.drawImage(img, 0, 0, width, height);
        const compressedBase64 = canvas.toDataURL('image/jpeg', 0.7);
        resolve(compressedBase64);
      };

      img.src = URL.createObjectURL(file);
    });
  };

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      toast({
        title: "File too large",
        description: "Please select an image smaller than 5MB.",
        variant: "destructive",
      });
      return;
    }

    try {
      const compressedImage = await compressImage(file);
      updateProfileMutation.mutate({ avatar: compressedImage });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to process image.",
        variant: "destructive",
      });
    }
  };

  const handleCopy = async (text: string, type: string) => {
    await navigator.clipboard.writeText(text);
    setCopied(type);
    setTimeout(() => setCopied(null), 2000);
    toast({
      title: "Copied!",
      description: `${type} copied to clipboard.`,
    });
  };

  const handleFormSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const profileData = {
      username: formData.get('username'),
      displayName: formData.get('displayName'),
      bio: formData.get('bio'),
      twitterHandle: formData.get('twitterHandle'),
      telegramHandle: formData.get('telegramHandle'),
      discordHandle: formData.get('discordHandle'),
      websiteUrl: formData.get('websiteUrl'),
      customReferralCode: formData.get('customReferralCode'),
    };
    updateProfileMutation.mutate(profileData);
  };

  if (!connectedWallet) {
    return (
      <div className="min-h-screen bg-[#0a0f0c] flex items-center justify-center">
        <div className="text-center">
          <Wallet className="h-16 w-16 mx-auto mb-4 text-gray-400" />
          <h2 className="text-xl font-semibold mb-2">Connect Your Wallet</h2>
          <p className="text-gray-400">Please connect your wallet to access your profile.</p>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0a0f0c] flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#22cda6] mx-auto mb-4"></div>
          <p className="text-gray-400">Loading profile...</p>
        </div>
      </div>
    );
  }

  const referralLink = profile?.customReferralCode 
    ? `https://gemlaunch.io/?ref=${profile.customReferralCode}`
    : `https://gemlaunch.io/?ref=${profile?.referralCode || connectedWallet.slice(0, 8)}`;

  return (
    <div className="min-h-screen bg-[#0a0f0c] p-6">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <User className="h-8 w-8 text-[#22cda6]" />
            <h1 className="text-2xl font-bold text-white">Profile Settings</h1>
          </div>
          <Button
            onClick={() => setIsEditing(!isEditing)}
            variant={isEditing ? "outline" : "default"}
            className={isEditing ? "border-[#22cda6] text-[#22cda6]" : "bg-[#22cda6] hover:bg-[#22cda6]/90 text-black"}
          >
            {isEditing ? "Cancel" : "Edit Profile"}
          </Button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Profile Information */}
          <div className="lg:col-span-2 space-y-6">
            <Card className="bg-[#253935] border-[#22cda6]/20">
              <CardHeader>
                <CardTitle className="text-white">Profile Information</CardTitle>
              </CardHeader>
              <CardContent>
                {isEditing ? (
                  <form onSubmit={handleFormSubmit} className="space-y-6">
                    {/* Basic Info Section */}
                    <div className="space-y-4">
                      <h3 className="text-[#22cda6] font-gilroy-bold text-lg">Basic Information</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <Label htmlFor="username">Username</Label>
                          <Input 
                            name="username"
                            defaultValue={profile?.username || ""}
                            placeholder="Enter your username"
                            className="bg-[#0f1713] border-[#22cda6]/20 text-[#22cda6] focus:border-[#22cda6]"
                          />
                        </div>

                        <div>
                          <Label htmlFor="displayName">Display Name</Label>
                          <Input 
                            name="displayName"
                            defaultValue={profile?.displayName || ""}
                            placeholder="Enter your display name"
                            className="bg-[#0f1713] border-[#22cda6]/20 text-[#22cda6] focus:border-[#22cda6]"
                          />
                        </div>
                      </div>

                      <div>
                        <Label htmlFor="bio">Bio</Label>
                        <Textarea 
                          name="bio"
                          defaultValue={profile?.bio || ""}
                          placeholder="Tell us about yourself..."
                          rows={3}
                          className="bg-[#0f1713] border-[#22cda6]/20 text-[#22cda6] focus:border-[#22cda6] resize-none"
                        />
                      </div>
                    </div>

                    {/* Social Media Section - Critical for Point Rewards */}
                    <div className="space-y-4 border-t border-[#22cda6]/20 pt-6">
                      <div className="flex items-center gap-3">
                        <MessageCircle className="w-5 h-5 text-[#22cda6]" />
                        <h3 className="text-[#22cda6] font-gilroy-bold text-lg">Social Media Accounts</h3>
                        <div className="px-2 py-1 bg-[#22cda6]/10 border border-[#22cda6]/30 rounded text-xs text-[#22cda6]">
                          Required for Social Rewards
                        </div>
                      </div>
                      <p className="text-sm text-gray-400 mb-4">
                        Add your social media usernames to earn points for authentic Gemlaunch mentions and engagement.
                      </p>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <Label htmlFor="twitterHandle" className="flex items-center gap-2">
                            <span>X (Twitter) Username</span>
                            <span className="text-xs text-[#22cda6]">● Required for mention rewards</span>
                          </Label>
                          <Input 
                            name="twitterHandle"
                            defaultValue={profile?.twitterHandle || ""}
                            placeholder="@yourhandle"
                            className="bg-[#0f1713] border-[#22cda6]/20 text-[#22cda6] focus:border-[#22cda6]"
                          />
                        </div>

                        <div>
                          <Label htmlFor="discordHandle" className="flex items-center gap-2">
                            <span>Discord Username</span>
                            <span className="text-xs text-[#22cda6]">● Required for community rewards</span>
                          </Label>
                          <Input 
                            name="discordHandle"
                            defaultValue={profile?.discordHandle || ""}
                            placeholder="username#1234"
                            className="bg-[#0f1713] border-[#22cda6]/20 text-[#22cda6] focus:border-[#22cda6]"
                          />
                        </div>
                      </div>
                    </div>

                    {/* Additional Contact Info */}
                    <div className="space-y-4 border-t border-[#22cda6]/20 pt-6">
                      <h3 className="text-[#22cda6] font-gilroy-bold text-lg">Additional Information</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <Label htmlFor="websiteUrl">Website URL</Label>
                          <Input 
                            name="websiteUrl"
                            defaultValue={profile?.websiteUrl || ""}
