  const getStatusColor = (status: string) => {
    switch (status) {
      case 'presale': return 'bg-blue-600';
      case 'fairlaunch': return 'bg-[#22cda6]';
      case 'dutch_auction': return 'bg-orange-600';
      case 'completed': return 'bg-gray-600';
      default: return 'bg-gray-600';
