                              • Prevents self-referral farming
                            </div>
                          </div>
                        </TooltipContent>
                      </Tooltip>
                    </TooltipProvider>

                    <div className="text-center">
                      <div className="text-white font-bold text-lg">
                        {formatPoints(leader.totalReferralPoints)}
                      </div>
                      <div className="text-xs text-gray-400">Points</div>
