'use client';

import { useEffect, useMemo } from 'react';
import { ExtendEthereum } from 'global';
import replaceBrowserHistory from '@dapp/utils/replaceBrowserHistory';
import { ConnectorData, useAccount } from 'wagmi';
import { CHAIN_QUERY_NAME } from '@/config/chains';
import { useAppDispatch } from '@/state';
import { clearUserStates } from '@/utils/clearUserStates';
import { useSessionChainId } from './useSessionChainId';
import { useActiveChainId } from './useActiveChainId';

export const useAccountEventListener = () => {
    // const { account, chainId, connector } = useActiveWeb3React()
    const { chainId } = useActiveChainId();
    const { connector, address } = useAccount();
    const [, setSessionChainId] = useSessionChainId();
    const dispatch = useAppDispatch();

    const isBloctoMobileApp = useMemo(() => {
        return (
            typeof window !== 'undefined' && Boolean((window.ethereum as ExtendEthereum)?.isBlocto)
        );
    }, []);

    useEffect(() => {
        if (address && connector) {
            const handleUpdateEvent = (e: ConnectorData) => {
                if (e?.chain?.id && !(e?.chain?.unsupported ?? false)) {
                    replaceBrowserHistory('chain', CHAIN_QUERY_NAME[e.chain.id]);
                    setSessionChainId(e.chain.id);
                }
                // Blocto in-app browser throws change event when no account change which causes user state reset therefore
                // this event should not be handled to avoid unexpected behaviour.
                if (!isBloctoMobileApp) {
                    clearUserStates(dispatch, { chainId, newChainId: e?.chain?.id });
                }
            };

            const handleDeactiveEvent = () => {
                clearUserStates(dispatch, { chainId });
            };

            connector.addListener('disconnect', handleDeactiveEvent);
            connector.addListener('change', handleUpdateEvent);

            return () => {
                connector.removeListener('disconnect', handleDeactiveEvent);
                connector.removeListener('change', handleUpdateEvent);
            };
        }
        return undefined;
    }, [chainId, dispatch, address, connector, setSessionChainId, isBloctoMobileApp]);
};

'use client';
import { ChainId } from '@dapp/chains';
import { atom, useAtomValue } from 'jotai';
import { useRouter, useSearchParams } from 'next/navigation';
import { useDeferredValue } from 'react';
import { isChainSupported } from '@/utils/wagmi';
import { useNetwork } from 'wagmi';
import { getChainId } from '@/config/chains';
import { useSessionChainId } from './useSessionChainId';

const queryChainIdAtom = atom(-1); // -1 unload, 0 no chainId on query

queryChainIdAtom.onMount = (set) => {
    const params = new URL(window.location.href).searchParams;
    let chainId;
    // chain has higher priority than chainId
    // keep chainId for backward compatible
    const c = params.get('chain');
    if (!c) {
        chainId = params.get('chainId');
    } else {
        chainId = getChainId(c);
    }
    if (chainId && isChainSupported(+chainId)) {
        set(+chainId);
    } else {
        set(0);
    }
};

export function useLocalNetworkChain() {
    const [sessionChainId] = useSessionChainId();
    // useRouter is kind of slow, we only get this query chainId once
    const queryChainId = useAtomValue(queryChainIdAtom);

    const chain = useSearchParams().get('chain');
    const chainId = +(sessionChainId || getChainId(chain as string) || queryChainId);

    if (isChainSupported(chainId)) {
        return chainId;
    }

    return undefined;
}

export const useActiveChainId = () => {
    const localChainId = useLocalNetworkChain();
    const queryChainId = useAtomValue(queryChainIdAtom);

    const { chain } = useNetwork();
    const chainId = localChainId ?? chain?.id ?? (queryChainId >= 0 ? ChainId.BSC : undefined);

    const isNotMatched = useDeferredValue(chain && localChainId && chain.id !== localChainId);

    return {
        chainId,
        isWrongNetwork: (chain?.unsupported ?? false) || isNotMatched,
        isNotMatched,
    };
};

'use client';

import { useWeb3React } from '@dapp/wagmi';
import { useRouter } from 'next/router';
import { useEffect, useRef } from 'react';
import { EXCHANGE_PAGE_PATHS } from '@/config/constants/exchange';
import { isChainSupported } from '@/utils/wagmi';
import { ChainId } from '@dapp/chains';
import { CHAIN_QUERY_NAME, getChainId } from 'config/chains';
import { getHashFromRouter } from '@/utils/getHashFromRouter';
import { useSwitchNetworkLoading } from './useSwitchNetworkLoading';
import { useActiveChainId } from './useActiveChainId';

export function useNetworkConnectorUpdater() {
    const { chainId } = useActiveChainId();
    const previousChainIdRef = useRef(chainId);
    const [loading] = useSwitchNetworkLoading();
    const router = useRouter();

    useEffect(() => {
        const setPrevChainId = () => {
            previousChainIdRef.current = chainId;
        };
        if (loading || !router.isReady) return setPrevChainId();
        const parsedQueryChainId = getChainId(router.query.chain as string);

        if (!parsedQueryChainId && chainId === ChainId.BSC) return setPrevChainId();
        if (parsedQueryChainId !== chainId && isChainSupported(chainId)) {
            const removeQueriesFromPath =
                previousChainIdRef.current !== chainId &&
                EXCHANGE_PAGE_PATHS.some((item) => {
                    return router.pathname.startsWith(item);
                });
            const uriHash = getHashFromRouter(router)?.[0];
            const { chainId: _chainId, ...omittedQuery } = router.query;
            router.replace(
                {
                    query: {
                        ...(!removeQueriesFromPath && omittedQuery),
                        chain: CHAIN_QUERY_NAME[chainId],
                    },
                    ...(uriHash && { hash: uriHash }),
                },
                undefined,
                {
                    shallow: true,
                    scroll: false,
                },
            );
        }
        return setPrevChainId();
    }, [chainId, loading, router]);
}

