export enum ApprovalState {
    UNKNOWN,
    NOT_APPROVED,
    PENDING,
    APPROVED,
}

// returns a variable indicating the state of the approval and a function which approves if necessary or early returns
export function useApproveCallback(
    amountToApprove?: CurrencyAmount<Currency>,
    spender?: string,
    options: {
        addToTransaction;
        targetAmount?: bigint;
    } = {
        addToTransaction: true,
    },
): {
    approvalState: ApprovalState;
    approveCallback: (exactAmount?: bigint) => Promise<SendTransactionResult>;
    revokeCallback: () => Promise<SendTransactionResult>;
    currentAllowance: CurrencyAmount<Currency> | undefined;
    isPendingError: boolean;
} {
    const { addToTransaction = true, targetAmount } = options;
    const { address: account } = useAccount();
    const { callWithGasPrice } = useCallWithGasPrice();

    const token = amountToApprove?.currency?.isToken ? amountToApprove.currency : undefined;
    const { allowance: currentAllowance, refetch } = useTokenAllowance(
        token,
        account ?? undefined,
        spender,
    );
    const pendingApproval = useHasPendingApproval(token?.address, spender);
    const [pending, setPending] = useState<boolean>(pendingApproval);
    const [isPendingError, setIsPendingError] = useState<boolean>(false);

    useEffect(() => {
        if (pendingApproval) {
            setPending(true);
        } else if (pending) {
            refetch().then(() => {
                setPending(false);
            });
        }
    }, [pendingApproval, pending, refetch]);

    // check the current approval status
    const approvalState: ApprovalState = useMemo(() => {
        if (!amountToApprove || !spender) return ApprovalState.UNKNOWN;
        if (amountToApprove.currency?.isNative) return ApprovalState.APPROVED;
        // we might not have enough data to know whether or not we need to approve
        if (!currentAllowance) return ApprovalState.UNKNOWN;

        // amountToApprove will be defined if currentAllowance is
        return currentAllowance.lessThan(amountToApprove)
            ? pending
                ? ApprovalState.PENDING
                : ApprovalState.NOT_APPROVED
            : ApprovalState.APPROVED;
    }, [amountToApprove, currentAllowance, pending, spender]);

    const tokenContract = useTokenContract(token?.address);
    const addTransaction = useTransactionAdder();

    const approve = useCallback(
        async (overrideAmountApprove?: bigint): Promise<SendTransactionResult> => {
            if (
                approvalState !== ApprovalState.NOT_APPROVED &&
                isUndefinedOrNull(overrideAmountApprove)
            ) {
                // toast.error('Approve was called unnecessarily');
                console.error('approve was called unnecessarily');
                setIsPendingError(true);
                return undefined;
            }
            if (!token) {
                // toastError(t('Error'), t('No token'))
                console.error('no token');
                // return undefined
            }

            if (!tokenContract) {
                // toast.error('Cannot find contract of the token %tokenAddress%');
                console.error('tokenContract is null');
                setIsPendingError(true);
                return undefined;
            }

            if (!amountToApprove && isUndefinedOrNull(overrideAmountApprove)) {
                // toast.error('Missing amount to approve');
                console.error('missing amount to approve');
                setIsPendingError(true);
                return undefined;
            }

            if (!spender) {
                // toast.error('No spender');
                console.error('no spender');
                setIsPendingError(true);
                return undefined;
            }

            let useExact = false;

            const estimatedGas = await tokenContract.estimateGas
                .approve([spender as Address, MaxUint256], {
                    account: tokenContract.account,
                } as never)
                .catch(() => {
                    // general fallback for tokens who restrict approval amounts
                    useExact = true;
                    return tokenContract.estimateGas
                        .approve(
                            [
                                spender as Address,
                                overrideAmountApprove ??
                                    amountToApprove?.quotient ??
                                    targetAmount ??
                                    MaxUint256,
                            ],
                            {
                                account: tokenContract.account,
                            } as never,
                        )
                        .catch((e) => {
                            console.error('estimate gas failure', e);
                            // toast.error(
                            //     'Unexpected error. Could not estimate gas for the approve.',
                            // );
                            setIsPendingError(true);
                            return null;
                        });
                });

            if (!estimatedGas) return undefined;

            return callWithGasPrice(
                tokenContract,
                'approve' as const,
                [
                    spender as Address,
                    overrideAmountApprove ??
                        (useExact
                            ? amountToApprove?.quotient ?? targetAmount ?? MaxUint256
                            : MaxUint256),
                ],
                {
                    gas: calculateGasMargin(estimatedGas),
                },
            )
                .then((response) => {
                    if (addToTransaction) {
                        addTransaction(response, {
                            summary: `Approve ${
                                overrideAmountApprove ?? amountToApprove?.currency?.symbol
                            }`,
                            translatableSummary: {
                                text: 'Approve %symbol%',
                                data: {
                                    symbol:
                                        overrideAmountApprove?.toString() ??
                                        amountToApprove?.currency?.symbol,
                                },
                            },
                            approval: { tokenAddress: token?.address, spender },
                            type: 'approve',
                        });
                    }
                    return response;
                })
                .catch((error: any) => {
                    logError(error);
                    console.error('Failed to approve token', error);
                    if (!isUserRejected(error)) {
                        // toast.error(error.message);
                    }
                    throw error;
                });
        },
        [
            approvalState,
            token,
            tokenContract,
            amountToApprove,
            spender,
            callWithGasPrice,
            targetAmount,
            // toastError,
            addToTransaction,
            addTransaction,
        ],
    );

    const approveCallback = useCallback(
        (exactAmount?: bigint) => {
            return approve(exactAmount || undefined);
        },
        [approve],
    );

    const revokeCallback = useCallback(() => {
        return approve(0n);
    }, [approve]);

    return { approvalState, approveCallback, revokeCallback, currentAllowance, isPendingError };
}

export function useApproveCallbackFromAmount({
    token,
    minAmount,
    targetAmount,
    spender,
    addToTransaction,
}: {
    token?: ERC20Token;
    minAmount?: bigint;
    targetAmount?: bigint;
    spender?: string;
    addToTransaction?: boolean;
}) {
    const amountToApprove = useMemo(() => {
        if (!minAmount || !token) return undefined;
        return CurrencyAmount.fromRawAmount(token, minAmount);
    }, [minAmount, token]);

    return useApproveCallback(amountToApprove, spender, {
        addToTransaction,
        targetAmount,
    });
}

