        queryKey: [`Launchpad ${address}`],
        queryFn: async () => request(SUBSQUID_URLS[chainId], GET_SINGLE_LAUNCHPAD, { address }),
    });

    return {
        data,
        refetch,
        isLoading,
        isError,
        error,
        isFetching,
    };
};

