import { CurrencyAmount, Pair, Currency, pancakePairV2ABI } from '@dapp/sdk';
import { useMemo } from 'react';

import { useMultipleContractSingleData } from '../state/multicall/hooks';
import { wrappedCurrency } from '../utils/wrappedCurrency';
import { useActiveChainId } from './useActiveChainId';

export enum PairState {
    LOADING,
    NOT_EXISTS,
    EXISTS,
    INVALID,
}

export function useV2Pairs(
    currencies: [Currency | undefined, Currency | undefined][],
): [PairState, Pair | null][] {
    const { chainId } = useActiveChainId();

    const tokens = useMemo(
        () =>
            currencies.map(([currencyA, currencyB]) => [
                wrappedCurrency(currencyA, chainId),
                wrappedCurrency(currencyB, chainId),
            ]),
        [chainId, currencies],
    );

    const pairAddresses = useMemo(
        () =>
            tokens.map(([tokenA, tokenB]) => {
                try {
                    return tokenA && tokenB && !tokenA.equals(tokenB)
                        ? Pair.getAddress(tokenA, tokenB)
                        : undefined;
                } catch (error: any) {
                    // Debug Invariant failed related to this line
                    console.error(
                        error.msg,
                        `- pairAddresses: ${tokenA?.address}-${tokenB?.address}`,
                        `chainId: ${tokenA?.chainId}`,
                    );

                    return undefined;
                }
            }),
        [tokens],
    );
    const results = useMultipleContractSingleData({
        addresses: pairAddresses,
        abi: pancakePairV2ABI,
        functionName: 'getReserves',
    });

    return useMemo(() => {
        return results.map((result, i) => {
            const { result: reserves, loading } = result;
            const tokenA = tokens[i][0];
            const tokenB = tokens[i][1];

            if (loading) return [PairState.LOADING, null];
            if (!tokenA || !tokenB || tokenA.equals(tokenB)) return [PairState.INVALID, null];
            if (!reserves) return [PairState.NOT_EXISTS, null];
            const [reserve0, reserve1] = reserves;
            const [token0, token1] = tokenA.sortsBefore(tokenB)
                ? [tokenA, tokenB]
                : [tokenB, tokenA];
            return [
                PairState.EXISTS,
                new Pair(
                    CurrencyAmount.fromRawAmount(token0, reserve0.toString()),
                    CurrencyAmount.fromRawAmount(token1, reserve1.toString()),
                ),
            ];
        });
    }, [results, tokens]);
}

export function useV2Pair(tokenA?: Currency, tokenB?: Currency): [PairState, Pair | null] {
    const pairCurrencies = useMemo<[Currency, Currency][]>(
        () => [[tokenA, tokenB]],
        [tokenA, tokenB],
    );
    return useV2Pairs(pairCurrencies)[0];
}

