import { Currency } from '@dapp/sdk';
import { SmartRouter, V2Pool } from '@dapp/smart-router/evm';
import { useMemo, useRef } from 'react';
import useSWR from 'swr';

import { infoClientWithChain, v3Clients } from 'utils/graphql';
import { getViemClients } from 'utils/viem';
import { POOLS_FAST_REVALIDATE } from 'config/pools';

export interface V2PoolsHookParams {
    // Used for caching
    key?: string;
    blockNumber?: number;
    enabled?: boolean;
}

export interface V2PoolsResult {
    pools: V2Pool[] | null;
    loading: boolean;
    syncing: boolean;
    blockNumber?: number;
    refresh: () => void;
}

export function useV2CandidatePools(
    currencyA?: Currency,
    currencyB?: Currency,
    options?: V2PoolsHookParams,
): V2PoolsResult {
    const refreshInterval = useMemo(() => {
        const chainId = currencyA?.chainId;
        if (!chainId) {
            return 0;
        }
        return POOLS_FAST_REVALIDATE[chainId] || 0;
    }, [currencyA]);

    const key = useMemo(() => {
        if (!currencyA || !currencyB || currencyA.wrapped.equals(currencyB.wrapped)) {
            return '';
        }
        const symbols = currencyA.wrapped.sortsBefore(currencyB.wrapped)
            ? [currencyA.symbol, currencyB.symbol]
            : [currencyB.symbol, currencyA.symbol];
        return [...symbols, currencyA.chainId].join('_');
    }, [currencyA, currencyB]);

    const fetchingBlock = useRef<string | null>(null);
    const queryEnabled = Boolean(options?.enabled && key);
    const result = useSWR<{
        pools: V2Pool[];
        key?: string;
        blockNumber?: number;
    }>(
        queryEnabled && key && ['V2_Candidate_Pools', key],
        async () => {
            fetchingBlock.current = options?.blockNumber?.toString();
            try {
                const pools = await SmartRouter.getV2CandidatePools({
                    currencyA,
                    currencyB,
                    v2SubgraphProvider: ({ chainId }) => infoClientWithChain(chainId),
                    v3SubgraphProvider: ({ chainId }) => v3Clients[chainId],
                    onChainProvider: getViemClients,
                });
                return {
                    pools,
                    key,
                    blockNumber: options?.blockNumber,
                };
            } finally {
                fetchingBlock.current = null;
            }
        },
        {
            refreshInterval,
            errorRetryCount: 3,
            revalidateOnFocus: false,
        },
    );

    const { mutate, data, isLoading, isValidating } = result;

    return {
        pools: data?.pools ?? null,
        loading: isLoading,
        syncing: isValidating,
        blockNumber: data?.blockNumber,
        refresh: mutate,
    };
}

import { Currency } from '@dapp/sdk';
import { SmartRouter, V3Pool } from '@dapp/smart-router/evm';
import { Tick } from '@dapp/v3-sdk';
import { useMemo } from 'react';
import useSWRImmutable from 'swr/immutable';
import { useQuery } from '@tanstack/react-query';

import { v3Clients } from 'utils/graphql';
import { getViemClients } from 'utils/viem';
import { POOLS_FAST_REVALIDATE, POOLS_SLOW_REVALIDATE } from 'config/pools';

import { getPoolTicks } from './v3/useAllV3TicksQuery';

export interface V3PoolsHookParams {
    // Used for caching
    key?: string;
    blockNumber?: number;
    enabled?: boolean;
}

export interface V3PoolsResult {
    refresh: () => void;
    pools: V3Pool[] | null;
    loading: boolean;
    syncing: boolean;
    blockNumber?: number;
    error?: Error;
}

export function useV3CandidatePools(
    currencyA?: Currency,
    currencyB?: Currency,
    options?: V3PoolsHookParams,
): V3PoolsResult {
    const {
        pools: candidatePoolsWithoutTicks,
        loading: isLoading,
        syncing: isValidating,
        key,
        blockNumber,
        refresh,
        error,
    } = useV3CandidatePoolsWithoutTicks(currencyA, currencyB, options);

    const {
        data,
        isLoading: ticksLoading,
        isValidating: ticksValidating,
    } = useV3PoolsWithTicks(candidatePoolsWithoutTicks, {
        key,
        blockNumber,
        enabled: options?.enabled,
    });

    const candidatePools = data?.pools ?? null;

    return {
        refresh,
        error,
        pools: candidatePools,
        loading: isLoading || ticksLoading,
        syncing: isValidating || ticksValidating,
        blockNumber: data?.blockNumber,
    };
}

export function useV3CandidatePoolsWithoutTicks(
    currencyA?: Currency,
    currencyB?: Currency,
    options?: V3PoolsHookParams,
) {
    const key = useMemo(() => {
        if (!currencyA || !currencyB || currencyA.wrapped.equals(currencyB.wrapped)) {
            return '';
        }
        const symbols = currencyA.wrapped.sortsBefore(currencyB.wrapped)
            ? [currencyA.symbol, currencyB.symbol]
            : [currencyB.symbol, currencyA.symbol];
        return [...symbols, currencyA.chainId].join('_');
    }, [currencyA, currencyB]);

    const refetchInterval = useMemo(() => {
        if (!currencyA?.chainId) {
            return 0;
        }
        return POOLS_FAST_REVALIDATE[currencyA.chainId] || 0;
    }, [currencyA?.chainId]);

    const {
        data,
        refetch,
        isLoading,
        isFetching,
        error: errorMsg,
    } = useQuery({
        queryKey: ['v3_candidate_pools', key],
        queryFn: async () => {
            const pools = await SmartRouter.getV3CandidatePools({
                currencyA,
                currencyB,
                subgraphProvider: ({ chainId }) => v3Clients[chainId],
                onChainProvider: getViemClients,
                blockNumber: options?.blockNumber,
            });
            return {
                key,
                pools,
                blockNumber: options?.blockNumber,
            };
        },
        retry: 2,
        staleTime: refetchInterval,
        refetchInterval,
        refetchOnWindowFocus: false,
        enabled: Boolean(currencyA && currencyB && key && options?.enabled),
    });

    const error = useMemo(() => errorMsg && new Error(errorMsg as string), [errorMsg]);

    return {
        refresh: refetch,
        pools: data?.pools ?? null,
        loading: isLoading,
        syncing: isFetching,
        blockNumber: data?.blockNumber,
        key: data?.key,
        error,
    };
}

export function useV3PoolsWithTicks(
    pools: V3Pool[] | null | undefined,
    { key, blockNumber, enabled = true }: V3PoolsHookParams = {},
) {
    const refreshInterval = useMemo(() => {
        const chainId = pools?.[0]?.token0?.chainId;
        if (!chainId) {
            return 0;
        }
        return POOLS_SLOW_REVALIDATE[chainId] || 0;
    }, [pools]);

    const poolsWithTicks = useSWRImmutable(
        key && pools && enabled ? ['v3_pool_ticks', key] : null,
        async () => {
            if (!pools) {
                throw new Error('Invalid pools to get ticks');
            }
            const label = `[V3_POOL_TICKS] ${key} ${blockNumber?.toString()}`;
            SmartRouter.metric(label);
            const poolTicks = await Promise.all(
                pools.map(async (pool) => {
                    const { token0 } = pool;
                    return getPoolTicks(token0.chainId, SmartRouter.getPoolAddress(pool)).then(
                        (data) => {
                            return data.map(
                                ({ tick, liquidityNet, liquidityGross }) =>
                                    new Tick({ index: Number(tick), liquidityNet, liquidityGross }),
                            );
                        },
                    );
                }),
            );
            SmartRouter.metric(label, poolTicks);
            return {
                pools: pools?.map((pool, i) => ({
                    ...pool,
                    ticks: poolTicks[i],
                })),
                key,
                blockNumber,
            };
        },
        {
            refreshInterval,
            errorRetryCount: 3,
            revalidateOnFocus: false,
        },
    );

    return poolsWithTicks;
}

import { Currency, WNATIVE } from '@dapp/sdk';
import { useMemo } from 'react';
import tryParseAmount from '@dapp/utils/tryParseAmount';
import { useTransactionAdder } from 'state/transactions/hooks';
import { useCurrencyBalance } from 'state/wallet/hooks';
import useAccountActiveChain from 'hooks/useAccountActiveChain';
import { useWNativeContract } from './useContract';
import { useCallWithGasPrice } from './useCallWithGasPrice';

export enum WrapType {
    NOT_APPLICABLE,
    WRAP,
    UNWRAP,
}

const NOT_APPLICABLE = { wrapType: WrapType.NOT_APPLICABLE };
/**
 * Given the selected input and output currency, return a wrap callback
 * @param inputCurrency the selected input currency
 * @param outputCurrency the selected output currency
 * @param typedValue the user input value
 */
export default function useWrapCallback(
    inputCurrency: Currency | undefined,
    outputCurrency: Currency | undefined,
    typedValue: string | undefined,
): { wrapType: WrapType; execute?: undefined | (() => Promise<void>); inputError?: string } {
    const { account, chainId } = useAccountActiveChain();
    const { callWithGasPrice } = useCallWithGasPrice();
    const wbnbContract = useWNativeContract();
    const balance = useCurrencyBalance(account ?? undefined, inputCurrency);
    // we can always parse the amount typed as the input currency, since wrapping is 1:1
    const inputAmount = useMemo(
        () => tryParseAmount(typedValue, inputCurrency),
        [inputCurrency, typedValue],
    );
    const addTransaction = useTransactionAdder();

    return useMemo(() => {
        if (!wbnbContract || !chainId || !inputCurrency || !outputCurrency) return NOT_APPLICABLE;

        const sufficientBalance = inputAmount && balance && !balance.lessThan(inputAmount);

        if (inputCurrency?.isNative && WNATIVE[chainId]?.equals(outputCurrency)) {
            return {
                wrapType: WrapType.WRAP,
                execute:
                    sufficientBalance && inputAmount
                        ? async () => {
                              try {
                                  const txReceipt = await callWithGasPrice(
                                      wbnbContract,
                                      'deposit',
                                      undefined,
                                      {
                                          value: inputAmount.quotient,
                                      },
                                  );
                                  const amount = inputAmount.toSignificant(6);
                                  const native = inputCurrency.symbol;
                                  const wrap = WNATIVE[chainId].symbol;
                                  addTransaction(txReceipt, {
                                      summary: `Wrap ${amount} ${native} to ${wrap}`,
                                      translatableSummary: {
                                          text: 'Wrap %amount% %native% to %wrap%',
                                          data: { amount, native, wrap },
                                      },
                                      type: 'wrap',
                                  });
                              } catch (error) {
                                  console.error('Could not deposit', error);
                              }
                          }
                        : undefined,
                inputError: sufficientBalance
                    ? undefined
                    : `Insufficient ${inputCurrency.symbol} balance`,
            };
        }
        if (WNATIVE[chainId]?.equals(inputCurrency) && outputCurrency?.isNative) {
            return {
                wrapType: WrapType.UNWRAP,
                execute:
                    sufficientBalance && inputAmount
                        ? async () => {
                              try {
                                  const txReceipt = await callWithGasPrice(
                                      wbnbContract,
                                      'withdraw',
                                      [inputAmount.quotient],
                                  );
                                  const amount = inputAmount.toSignificant(6);
                                  const wrap = WNATIVE[chainId].symbol;
                                  const native = outputCurrency.symbol;
                                  addTransaction(txReceipt, {
                                      summary: `Unwrap ${amount} ${wrap} to ${native}`,
                                      translatableSummary: {
                                          text: 'Unwrap %amount% %wrap% to %native%',
                                          data: { amount, wrap, native },
                                      },
                                  });
                              } catch (error) {
                                  console.error('Could not withdraw', error);
                              }
                          }
                        : undefined,
                inputError: sufficientBalance
                    ? undefined
                    : // : t('Insufficient %symbol% balance', { symbol: inputCurrency.symbol }),
                      `Insufficient ${inputCurrency.symbol} balance`,
            };
        }
        return NOT_APPLICABLE;
    }, [
        wbnbContract,
        chainId,
        inputCurrency,
        outputCurrency,
        inputAmount,
        balance,
        addTransaction,
        callWithGasPrice,
    ]);
}

export function useIsWrapping(
    currencyA: Currency | undefined,
    currencyB: Currency | undefined,
    value?: string,
) {
    const { wrapType } = useWrapCallback(currencyA, currencyB, value);

    return wrapType !== WrapType.NOT_APPLICABLE;
}

