export const handleMergeDuplicates = (allocations: string): string => {
    const transactions = allocations
        .trim()
        .split('\n')
        .map((line) => {
            const [addr, amount] = line.split(',');
            return { address: addr, amount: +amount };
        });

    const combinedTransactionsMap: Map<string, number> = new Map();

    // Iterate over transactions array to combine transactions
    transactions.forEach((transaction) => {
        const { address, amount } = transaction;
        if (combinedTransactionsMap.has(address)) {
            // If address already exists, add amount to existing amount
            const existingAmount = combinedTransactionsMap.get(address)!;
            combinedTransactionsMap.set(address, existingAmount + amount);
        } else {
            // If address doesn't exist, set amount for address
            combinedTransactionsMap.set(address, amount);
        }
    });

    // Convert map back to array of transactions
    const combinedTransactions: { address: string; amount: number }[] = [];
    combinedTransactionsMap.forEach((amount, address) => {
        combinedTransactions.push({ address, amount });
    });

    return combinedTransactions.map((x) => `${x.address},${x.amount}`).join('\n');
};

export const handleRemoveDuplicates = (allocations: string): string => {
    const seen: { [key: string]: boolean } = {};
    const result: { address: string; amount: number }[] = [];

    const data = allocations
        .trim()
        .split('\n')
        .map((line) => {
            const [addr, amount] = line.split(',');
            return { address: addr, amount: +amount };
        });

    for (const e of data) {
        if (!seen[e.address]) {
            seen[e.address] = true;
            result.push(e);
        }
    }

    return result.map((x) => `${x.address},${x.amount}`).join('\n');
};

import { atomWithStorage } from 'jotai/utils';
import { createJSONStorage } from 'jotai/vanilla/utils';
import { logError } from './sentry';

export default function atomWithStorageWithErrorCatch<Value>(
    key: string,
    initialValue: Value,
    getStringStorage?: () => Storage,
) {
    const tryCatchStorage = createJSONStorage<Value>(() => {
        const getStorage =
            getStringStorage ||
            (() =>
                typeof window !== 'undefined'
                    ? window.localStorage
                    : (undefined as unknown as Storage));
        const stringStorage = getStorage?.();
        return stringStorage
            ? {
                  removeItem: (storageKey: string) => {
                      stringStorage.removeItem(storageKey);
                  },
                  getItem: (storageKey: string) => {
                      return stringStorage.getItem(storageKey);
                  },
                  setItem: (storageKey: string, newValue: string) => {
                      try {
                          stringStorage.setItem(storageKey, newValue);
                      } catch (error) {
                          // Add try-catch to avoid breaking the app when localStorage is full.
                          console.error(`localStorage error with key ${storageKey}`);
                          logError(error);
                      }
                  },
              }
            : stringStorage;
    });
    return atomWithStorage(key, initialValue, tryCatchStorage);
}

export const calculatePercentage = (number: number, percent: number): number => {
    if (isNaN(number) || isNaN(percent)) {
        return 0;
    }
    // Calculate the percentage of the number
    const result = (percent / 100) * number;

    return result;
};

interface Props {
    totalAmount: number;
    TGEPercent: number;
    cyclePercent: number;
    unlockTime: number;
    intervalTime: number;
}

export interface VestingSchedule {
    amount: number;
    percentage: number;
    unlockTime: number;
}
/**
 * this function is responsible for calculating the
 * @param totalAmount
 *
 * @param TGEPercentage
 *
 * @param cyclePercentage
 *
 * @param unlockTime
 *
 * @param intervalTime
 *
 * @returns
 */
export function calculateVesting({
    totalAmount,
    TGEPercent,
    cyclePercent,
    unlockTime,
    intervalTime,
}: Props) {
    if (!totalAmount || !TGEPercent || !cyclePercent || !unlockTime || !intervalTime) return null;

    const TGEAmount = (totalAmount * TGEPercent) / 100;
    const amountAfterTGE = totalAmount - TGEAmount;
    const cycleShare = (totalAmount * cyclePercent) / 100;

    const totalInterval = Math.ceil(amountAfterTGE / cycleShare);

    const vestingSchedule: VestingSchedule[] = [];
    vestingSchedule.push({ amount: TGEAmount, percentage: TGEPercent, unlockTime });

    let remainingAmount = amountAfterTGE;

    for (let i = 0; i < totalInterval; i++) {
        const currentCycleAmount = remainingAmount >= cycleShare ? cycleShare : remainingAmount;
        const currentCyclePercentage = (currentCycleAmount * 100) / totalAmount;

        vestingSchedule.push({
            amount: currentCycleAmount,
            percentage: currentCyclePercentage,
            // eslint-disable-next-line no-param-reassign
            unlockTime: (unlockTime += intervalTime),
        });

        remainingAmount -= currentCycleAmount;
    }

    return vestingSchedule;
}

