}

export function shortenAddress(address: any, chars = 4): string {
    const parsed = isAddress(address);
    if (!parsed) {
        return address;
        // throw Error(`Invalid 'address' parameter '${address}'.`);
    }
    return `${parsed.substring(0, chars + 2)}...${parsed.substring(42 - chars)}`;
}

export const formatText = (text: string, showFullDescription: boolean, lineCount: number = 3) => {
    if (!text) return null;
    const lines = text.split('\n');
    if (lines.length > lineCount && !showFullDescription)
        return lines.slice(0, lineCount).join('\n');
    return text;
};

import numbro from 'numbro';

export const formatAmount = (number: number | string, digits = 2) => {
    const num = Number(number);

    if (num <= 0) return '0';

    if (!num) return '0';

    if (num < 0.001) return '<0.001';

    return numbro(num)
        .format({
            thousandSeparated: true,
            average: true,
            mantissa: num > 1000 ? 2 : digits,
            abbreviations: {
                million: 'M',
                billion: 'B',
                trillion: 'T',
            },
        })
        .toUpperCase();
};

