import { Currency, CurrencyAmount, Price, TradeType } from '@dapp/sdk'

import { BestTradeOptions, Pair, RouteType, StableSwapPair, TradeWithStableSwap } from './types'
import { getOutputToken, involvesToken } from './utils/pair'
import { stableSwapPairsByChainId } from './getStableSwapPairs'
import { getStableSwapFee, getStableSwapOutputAmount } from './onchain'
import { createTradeWithStableSwap, getFeePercent } from './stableSwap'

export async function getBestTradeFromStablePools(
  amount: CurrencyAmount<Currency>,
  output: Currency,
  { maxHops, provider }: BestTradeOptions,
) {
  const {
    currency: { chainId },
  } = amount
  const pairs = stableSwapPairsByChainId[chainId] || []
  const routes = computeAllRoutes(amount.currency, output, pairs, maxHops)
  const trades = await Promise.all(routes.map((r) => getStableTrade(amount, r, { provider })))
  if (!trades.length) {
    return null
  }
  let bestTrade = trades[0]
  for (let i = 1; i < trades.length; i += 1) {
    const trade = trades[i]
    if (trade.outputAmount.greaterThan(bestTrade.outputAmount)) {
      bestTrade = trade
    }
  }
  return bestTrade
}

async function getStableTrade(
  amountIn: CurrencyAmount<Currency>,
  pairs: StableSwapPair[],
  { provider }: Pick<BestTradeOptions, 'provider'>,
): Promise<TradeWithStableSwap<Currency, Currency, TradeType>> {
  let outputToken = amountIn.currency
  let outputAmount = amountIn
  const pairsWithPrice: Pair[] = []
  for (const pair of pairs) {
    const inputAmount = outputAmount
    const results = await Promise.all([
      getStableSwapOutputAmount(pair, inputAmount, { provider }),
      getStableSwapFee(pair, inputAmount, { provider }),
    ])
    outputAmount = results[0]
    const fees = results[1]
    outputToken = getOutputToken(pair, outputToken)
    const { fee, adminFee } = getFeePercent(inputAmount, outputAmount, fees)
    pairsWithPrice.push({
      ...pair,
      price: new Price({ baseAmount: inputAmount, quoteAmount: outputAmount.add(fees.fee) }),
      fee,
      adminFee,
    })
  }
  return createTradeWithStableSwap({
    routeType: RouteType.STABLE_SWAP,
    inputAmount: amountIn,
    outputAmount,
    pairs: pairsWithPrice,
    tradeType: TradeType.EXACT_INPUT,
  })
}

function computeAllRoutes(input: Currency, output: Currency, pairs: StableSwapPair[], maxHops = 3): StableSwapPair[][] {
  const poolsUsed = Array<boolean>(pairs.length).fill(false)
  const routes: StableSwapPair[][] = []

  const computeRoutes = (
    currencyIn: Currency,
    currencyOut: Currency,
    currentRoute: StableSwapPair[],
    _previousCurrencyOut?: Currency,
  ) => {
    if (currentRoute.length > maxHops) {
      return
    }

    if (currentRoute.length > 0 && involvesToken(currentRoute[currentRoute.length - 1], currencyOut)) {
      routes.push([...currentRoute])
      return
    }

    for (let i = 0; i < pairs.length; i++) {
      if (poolsUsed[i]) {
        // eslint-disable-next-line
        continue
      }

      const curPool = pairs[i]
      const previousCurrencyOut = _previousCurrencyOut || currencyIn

      if (!involvesToken(curPool, previousCurrencyOut)) {
        // eslint-disable-next-line
        continue
      }

      const currentTokenOut = getOutputToken(curPool, previousCurrencyOut)

      currentRoute.push(curPool)
      poolsUsed[i] = true
      computeRoutes(currencyIn, currencyOut, currentRoute, currentTokenOut)
      poolsUsed[i] = false
      currentRoute.pop()
    }
  }

  computeRoutes(input, output, [])

  return routes
}

import { Currency, CurrencyAmount, Pair, Trade, TradeType, isTradeBetter } from '@dapp/sdk'

import { BETTER_TRADE_LESS_HOPS_THRESHOLD } from '../evm/constants'
import { getAllCommonPairs as defaultGetAllCommonPairs } from './getAllCommonPairs'
import { BestTradeOptions } from './types'

export const getBestTradeFromV2ExactIn = createGetBestTradeFromV2(TradeType.EXACT_INPUT)

export const getBestTradeFromV2ExactOut = createGetBestTradeFromV2(TradeType.EXACT_OUTPUT)

export async function getBestTradeFromV2<
  TInput extends Currency,
  TOutput extends Currency,
  TTradeType extends TradeType,
>(amountIn: CurrencyAmount<TInput>, output: TOutput, tradeType: TTradeType, options: BestTradeOptions) {
  const getBestTrade = tradeType === TradeType.EXACT_INPUT ? getBestTradeFromV2ExactIn : getBestTradeFromV2ExactOut

  return getBestTrade(amountIn, output, options)
}

function createGetBestTradeFromV2<TTradeType extends TradeType>(tradeType: TTradeType) {
  function getBestTrade<In extends Currency, Out extends Currency>(
    pairs: Pair[],
    amountIn: CurrencyAmount<In>,
    output: Out,
    options: Omit<BestTradeOptions, 'provider' | 'getAllCommonPairs'>,
  ) {
    if (tradeType === TradeType.EXACT_INPUT) {
      return Trade.bestTradeExactIn(pairs, amountIn, output, options)
    }
    return Trade.bestTradeExactOut(pairs, output, amountIn, options)
  }

  return async function bestTradeFromV2<In extends Currency, Out extends Currency>(
    amountIn: CurrencyAmount<In>,
    output: Out,
    options: BestTradeOptions,
  ) {
    const { provider, allCommonPairs, ...restOptions } = options
    const { maxHops = 3 } = restOptions
    const getAllowedPairs = async () => {
      if (Array.isArray(allCommonPairs)) {
        return allCommonPairs
      }
      if (allCommonPairs) {
        return allCommonPairs(amountIn.currency, output)
      }
      return defaultGetAllCommonPairs(amountIn.currency, output, { provider })
    }
    const allowedPairs = await getAllowedPairs()

    if (!allowedPairs.length) {
      return null
    }

    if (maxHops === 1) {
      return getBestTrade(allowedPairs, amountIn, output, restOptions)[0] ?? null
    }

    // search through trades with varying hops, find best trade out of them
    let bestTradeSoFar: ReturnType<typeof getBestTrade<In, Out>>[number] | null = null
    for (let i = 1; i <= maxHops; i++) {
      const currentTrade: ReturnType<typeof getBestTrade<In, Out>>[number] | null =
        getBestTrade(allowedPairs, amountIn, output, {
          ...restOptions,
          maxHops: i,
          maxNumResults: 1,
        })[0] ?? null
      // if current trade is best yet, save it
      if (isTradeBetter(bestTradeSoFar, currentTrade, BETTER_TRADE_LESS_HOPS_THRESHOLD)) {
        bestTradeSoFar = currentTrade
      }
    }
    return bestTradeSoFar
  }
}

