import { red } from 'chalk';
import fs from 'fs';

import { GOERLI_CHAIN_ID } from '../../src/constants';

const deploymentFolderPath: { [key: number]: string } = {
  [GOERLI_CHAIN_ID]: 'deployments/goerli',
};

export const getContractAddress = async (
  contractName: string,
  chainId: number,
): Promise<string> => {
  let address = '';

  const deploymentPath = `${__dirname.slice(0, __dirname.lastIndexOf('/scripts/'))}/${deploymentFolderPath[chainId]
    }`;

  await fs.promises
    .readdir(deploymentPath, { withFileTypes: true })
    .then(async (files) => {
      files.reverse();

      for (const file of files) {
        if (file.name.startsWith(contractName)) {
          const filePath = `${deploymentPath}/${file.name}`;

          await fs.promises.readFile(filePath).then((content) => {
            const data = JSON.parse(content.toString());

            address = data.address;
          });
        }
      }
    })
    .catch((error) => {
      red(`Failed to retrieve ${contractName} address.`);
      console.log(error);
    });

  return address;
};

import { HardhatRuntimeEnvironment } from 'hardhat/types';
import {
  isBinance,
  isAvalancheFuji,
  isPolygon,
  isArbitrumGoerli,
  isOptimismGoerli,
} from './isNetwork';

export function getHardhatConfigFile(hardhat: HardhatRuntimeEnvironment) {
  let config;
  if (isBinance(hardhat)) {
    config = 'hardhat.config.bsc.js';
  } else if (isPolygon(hardhat)) {
    config = 'hardhat.config.polygon.js';
  } else if (isAvalancheFuji(hardhat)) {
    config = 'hardhat.config.avalanche.ts';
  } else if (isArbitrumGoerli(hardhat)) {
    config = 'hardhat.config.arbitrum.ts';
  } else if (isOptimismGoerli(hardhat)) {
    config = 'hardhat.config.optimism.ts';
  } else {
    config = '';
  }
  return config;
}

import { HardhatRuntimeEnvironment } from 'hardhat/types';

export function isBinance(hardhat: HardhatRuntimeEnvironment) {
  const network = hardhat.network.name;
  return /bsc/.test(network);
}

export function isPolygon(hardhat: HardhatRuntimeEnvironment) {
  const network = hardhat.network.name;
  return /polygon/.test(network) || /matic/.test(network) || /mumbai/.test(network);
}

export function isAvalancheFuji(hardhat: HardhatRuntimeEnvironment) {
  const network = hardhat.network.name;
  return /avalanche/.test(network) || /fuji/.test(network) || /avalancheFuji/.test(network);
}

export function isArbitrumGoerli(hardhat: HardhatRuntimeEnvironment) {
  const network = hardhat.network.name;
  return /arbitrumGoerli/.test(network);
}

export function isOptimismGoerli(hardhat: HardhatRuntimeEnvironment) {
  const network = hardhat.network.name;
  return /optimismGoerli/.test(network);
}

import { HardhatRuntimeEnvironment } from 'hardhat/types';
import { getHardhatConfigFile } from './getHardhatConfigFile';

export const verifyAddress = async (
  hardhat: HardhatRuntimeEnvironment,
  address: string,
  args: Array<any>,
) => {
  const network = hardhat.network.name;
  const config = getHardhatConfigFile(hardhat);
  console.log('Arguments: ', args);
  try {
    const result = await hardhat.run('verify:verify', {
      address: address,
      constructorArguments: args || [],
      config: config,
      network: network,
    });
    console.log('Verify Result: ', result);
  } catch (error) {
    console.log('Error: ', error);
  }
};

