                                        await trigger('softcap');
                                    }}
                                    helperText={<TextFieldError fieldName={errors?.hardcap} />}
                                />
                            )}
                        />
                    </Box>
                </Box>
                <Box sx={{ mt: '12px', ml: 2 }}>
