                loading ? <Skeleton
                    variant="rounded"
                    animation="wave"
                    height={370}
                    sx={{ width: '100%', borderRadius: '15px' }}
                /> : <PrimaryCard py={25}>
                    <>
                        <Infobar
                            dismissable={false}
                            message="Make sure the website is gemlaunch.io"
                            open={true}
                            variant="info"
                        />
                    </>

                    {
                        <SaleStatusInfo
                            hasEnded={hasEnded}
                            hasStarted={hasStarted}
                            counterStart={counterStart}
                            counterEnd={counterEnd}
                        />
                    }

                    {/* <Timer /> */}

                    <Box sx={{ mt: '10px' }}>
                        <LinearProgressCustom
                            bgColor="#BFFFD5"
                            value={getProgress(totalRaisedNum, hardCapNum)}
                        />
                        <Box
                            sx={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center',
                                gap: '10px',
                                marginTop: '3px',
                            }}
                        >
                            <Typography variant="h5" fontSize={12}>
                                {totalRaisedNum} {fundTokenSymbol}
                            </Typography>
                            <Typography fontSize={12}>
                                {formatUnits(hardCap, fundTokenDecimals ?? 18)}{' '}
                                {fundTokenSymbol ?? 'ETH'}
                            </Typography>
                        </Box>
                    </Box>

                    {hasEnded ? null : (
                        <Box sx={{ mt: '20px' }}>
                            <Box
                                sx={{
                                    display: 'flex',
                                    justifyContent: 'space-between',
                                    alignItems: 'center',
                                }}
                            >
                                <Typography fontSize={12} fontWeight={600} mb={1}>
                                    Max: {remainingBuyLimit} {fundTokenSymbol ?? 'ETH'}
                                </Typography>
                                <Typography fontSize={12} fontWeight={600} mb={1}>
                                    Bal: {Number(token?.formatted).toFixed(2)} {token?.symbol}
                                </Typography>
                            </Box>

                            <form onSubmit={handleSubmit(onSubmit)}>
                                <Controller
                                    name="buyAmount"
                                    control={control}
                                    render={({ field }) => {
                                        return (
                                            <TextField
                                                // label='buyAmount'
                                                {...field}
                                                sx={{
                                                    'input::-webkit-outer-spin-button': {
                                                        display: 'none',
                                                    },
                                                    'input::-webkit-inner-spin-button': {
                                                        display: 'none',
                                                    },
                                                }} // remove the icon at the end of the input
                                                type="number"
                                                placeholder="0.0"
                                                onChange={async (e) => {
                                                    field.onChange(e.target.value);
                                                    await trigger('buyAmount');
                                                }}
                                                onWheel={disableScroll}
                                                fullWidth
                                                error={!!errors?.buyAmount}
                                                disabled={hasBuyAmountReached}
                                                helperText={
                                                    <Typography
                                                        fontSize={12}
                                                        fontWeight={500}
                                                        sx={{ color: '#f25a67' }}
                                                    >
                                                        {errors?.buyAmount?.message}
                                                    </Typography>
                                                }
                                                InputProps={{
                                                    readOnly: !saleActive() ?? true,
                                                    endAdornment: (
                                                        <InputAdornment position="end">
                                                            <Button
                                                                variant="text"
                                                                sx={{ px: '16px' }}
                                                                disabled={hasBuyAmountReached}
                                                                onClick={async (e) => {
                                                                    e.preventDefault();
                                                                    setValue(
                                                                        'buyAmount',
                                                                        remainingBuyLimit ?? 0,
                                                                    );
                                                                    await trigger('buyAmount');
                                                                }}
                                                            >
                                                                MAX
                                                            </Button>
                                                        </InputAdornment>
                                                    ),
                                                }}
                                            />
                                        );
                                    }}
                                />

                                {buyAmount && !hasBuyAmountReached ? (
                                    <Typography fontSize="12px" color="#11B6DB">
                                        You will receive {tokenToReceive}
                                    </Typography>
                                ) : null}

                                {isNativeFundToken ? (
                                    <Button
                                        variant="contained"
                                        type="submit"
                                        size="small"
                                        disabled={disablePreSaleButton}
                                        sx={{ width: '100%', mt: 1 }}
                                    >
                                        {isIdle && `Buy with ${fundTokenSymbol}`}
                                        {isPending && <ButtonLoader text="Pending" />}
                                        {isProcessing && <ButtonLoader text="Processing" />}
                                    </Button>
                                ) : (
                                    <>
                                        {approvalState === ApprovalState.APPROVED && (
                                            <Button
                                                variant="contained"
                                                type="submit"
                                                size="small"
                                                disabled={disablePreSaleButton}
                                                sx={{ width: '100%', mt: 1 }}
                                            >
                                                {isIdle && `Buy with ${fundTokenSymbol}`}
                                                {isPending && <ButtonLoader text="Pending" />}
                                                {isProcessing && <ButtonLoader text="Processing" />}
                                            </Button>
                                        )}
                                        {approvalState !== ApprovalState.APPROVED && (
                                            <Button
                                                variant="contained"
                                                onClick={(e) => approveToken(e)}
                                                size="small"
                                                disabled={disablePreSaleButton}
                                                sx={{ width: '100%', mt: 1 }}
                                            >
                                                {isIdle && `Approve`}
                                                {isPending && <ButtonLoader text="Pending" />}
                                                {isProcessing && <ButtonLoader text="Processing" />}
                                            </Button>
                                        )}
                                    </>
                                )}
                            </form>
                        </Box>
                    )}

                    {hasEnded && (
                        <>
                            <Box
                                sx={{
                                    display: 'flex',
                                    justifyContent: 'center',
                                    alignItems: 'center',
                                    flexDirection: 'column',
                                    width: '100%',
                                    mt: 2,
                                }}
                            >
                                {totalRaisedNum < softCapNum ? null : vesting?.isVestingEnable ? (
                                    <Button
                                        variant="outlined"
                                        onClick={() => claimNow()}
                                        disabled={
                                            isClaimPending ||
                                            isClaimProcessing ||
                                            canClaimWithoutVesting ||
                                            userRemainingClaimable === 0n || !isTokenUnlocked ||
                                            !isPoolClosed
                                        }
                                        size="small"
                                        sx={{ width: '100%', marginBottom: '5px' }}
                                    >
                                        {isClaimIdle &&
                                            ` ${claimableToken === 0 ? 'Claimed' : !isPoolClosed ? "Pool not finalized" : `Claim  (${claimedToken}/${userTokens}) ${symbol}`}`}
                                        {isClaimPending && <ButtonLoader text="Pending..." />}
                                        {isClaimProcessing && <ButtonLoader text="Processing..." />}
                                    </Button>
                                ) : (
                                    <Button
                                        variant="outlined"
                                        onClick={() => claimNow()}
                                        disabled={
                                            isClaimPending ||
                                            isClaimProcessing ||
                                            canClaimWithoutVesting ||
                                            userRemainingClaimable === 0n ||
                                            !isPoolClosed
                                        }
                                        size="small"
                                        sx={{ width: '100%', marginBottom: '5px' }}
                                    >
                                        {isClaimIdle &&
                                            ` ${claimableToken === 0 ? 'Claimed' : !isPoolClosed ? "Pool not finalized" : `Claim`}`}
                                        {isClaimPending && <ButtonLoader text="Pending..." />}
                                        {isClaimProcessing && <ButtonLoader text="Processing..." />}
                                    </Button>
                                )}

                                {canRefund && userInvest > 0n && (
                                    <Button
                                        variant="outlined"
                                        onClick={() => refund()}
                                        disabled={isClaimPending || isClaimProcessing}
                                        size="small"
                                        sx={{ width: '100%' }}
                                    >
                                        {isClaimIdle &&
                                            `Refund (${userInvestment} ${fundTokenSymbol}) `}
                                        {isClaimPending && <ButtonLoader text="Pending..." />}
                                        {isClaimProcessing && <ButtonLoader text="Processing..." />}
                                    </Button>
                                )}
                            </Box>
                        </>
                    )}

                    {softCapNotReached && hasEnded && (
                        <Box
                            sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}
                            mt={1}
                        >
                            <Typography>This pool has Failed</Typography>
                        </Box>
                    )}

                    {isSaleClosed && !softCapNotReached && (
                        <Box
                            sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}
                            mt={1}
                        >
                            <Typography>This pool has {saleStatus}</Typography>
                        </Box>
                    )}

                </PrimaryCard>
            }

        </>
    );
};

