                endTime_lte: $currentTime
                isCancelled_eq: $isCancelled
            }
        ) {
            totalCount
            pageInfo {
                endCursor
                hasNextPage
            }
            edges {
                node {
                    id
                    initialRelease
                    currency
                    metadata {
                        socials {
                            logoUrl
                        }
