import { ChainId } from '@dapp/chains';
import { gql } from 'graphql-request';
import { TickMath } from '@dapp/v3-sdk';

export type AllV3TicksQuery = {
    ticks: Array<{
        tick: string;
        liquidityNet: string;
        liquidityGross: string;
    }>;
};

export type Ticks = AllV3TicksQuery['ticks'];
export type TickData = Ticks[number];

export default function useAllV3TicksQuery(poolAddress: string | undefined, interval: number) {
    const { chainId } = useActiveChainId();
    const { data, isLoading, error } = useSWRImmutable(
        poolAddress && v3Clients[chainId] ? `useAllV3TicksQuery-${poolAddress}-${chainId}` : null,
        async () => {
            return getPoolTicks(chainId, poolAddress);
        },
        {
            refreshInterval: interval,
        },
    );

    return useMemo(
        () => ({
            error,
            isLoading,
            data,
        }),
        [data, error, isLoading],
    );
}

export async function getPoolTicks(
    chainId: number,
    poolAddress: string,
    blockNumber?: string,
): Promise<Ticks> {
    const PAGE_SIZE = 1000;
    let allTicks = [];
    let lastTick = TickMath.MIN_TICK - 1;
    // eslint-disable-next-line no-constant-condition
    while (true) {
        // eslint-disable-next-line no-await-in-loop
        const ticks = await _getPoolTicksGreaterThan(
            chainId,
            poolAddress,
            lastTick,
            PAGE_SIZE,
            blockNumber,
        );
        allTicks = [...allTicks, ...ticks];
        const hasMore = ticks.length === PAGE_SIZE;

        if (!hasMore) {
            break;
        }
        lastTick = Number(ticks[ticks.length - 1].tick);
    }
    return allTicks;
}

async function _getPoolTicksGreaterThan(
    chainId: number,
    poolAddress: string,
    tick: number,
    pageSize: number,
    blockNumber?: string,
) {
    const client = v3Clients[<ChainId>(<unknown>chainId)];
    if (!client) {
        return [];
    }
    const response = await client.request(
        gql`
        query AllV3Ticks($poolAddress: String!, $lastTick: Int!, $pageSize: Int!) {
          ticks(
            first: $pageSize,
            ${blockNumber ? `block: { number: ${blockNumber} }` : ''}
            where: {
              poolAddress: $poolAddress,
              tickIdx_gt: $lastTick,
            },
            orderBy: tickIdx
          ) {
        tick: tickIdx
        liquidityNet
        liquidityGross
          }
        }
      `,
        {
            poolAddress: poolAddress.toLowerCase(),
            lastTick: tick,
            pageSize,
        },
    );
    return response.ticks;
}

import {
    ResultOf,
    DocumentTypeDecoration,
    TypedDocumentNode,
} from '@graphql-typed-document-node/core';
import { FragmentDefinitionNode } from 'graphql';
import { Incremental } from './graphql';

export type FragmentType<TDocumentType extends DocumentTypeDecoration<any, any>> =
    TDocumentType extends DocumentTypeDecoration<infer TType, any>
        ? [TType] extends [{ ' $fragmentName'?: infer TKey }]
            ? TKey extends string
                ? { ' $fragmentRefs'?: { [key in TKey]: TType } }
                : never
            : never
        : never;

// return non-nullable if `fragmentType` is non-nullable
export function useFragment<TType>(
    _documentNode: DocumentTypeDecoration<TType, any>,
    fragmentType: FragmentType<DocumentTypeDecoration<TType, any>>,
): TType;
// return nullable if `fragmentType` is nullable
export function useFragment<TType>(
    _documentNode: DocumentTypeDecoration<TType, any>,
    fragmentType: FragmentType<DocumentTypeDecoration<TType, any>> | null | undefined,
): TType | null | undefined;
// return array of non-nullable if `fragmentType` is array of non-nullable
export function useFragment<TType>(
    _documentNode: DocumentTypeDecoration<TType, any>,
    fragmentType: ReadonlyArray<FragmentType<DocumentTypeDecoration<TType, any>>>,
): ReadonlyArray<TType>;
// return array of nullable if `fragmentType` is array of nullable
export function useFragment<TType>(
    _documentNode: DocumentTypeDecoration<TType, any>,
    fragmentType:
        | ReadonlyArray<FragmentType<DocumentTypeDecoration<TType, any>>>
        | null
        | undefined,
): ReadonlyArray<TType> | null | undefined;
export function useFragment<TType>(
    _documentNode: DocumentTypeDecoration<TType, any>,
    fragmentType:
        | FragmentType<DocumentTypeDecoration<TType, any>>
        | ReadonlyArray<FragmentType<DocumentTypeDecoration<TType, any>>>
        | null
        | undefined,
): TType | ReadonlyArray<TType> | null | undefined {
    return fragmentType as any;
}

export function makeFragmentData<
    F extends DocumentTypeDecoration<any, any>,
    FT extends ResultOf<F>,
>(data: FT, _fragment: F): FragmentType<F> {
    return data as FragmentType<F>;
}
export function isFragmentReady<TQuery, TFrag>(
    queryNode: DocumentTypeDecoration<TQuery, any>,
    fragmentNode: TypedDocumentNode<TFrag>,
    data: FragmentType<TypedDocumentNode<Incremental<TFrag>, any>> | null | undefined,
): data is FragmentType<typeof fragmentNode> {
    const deferredFields = (
        queryNode as { __meta__?: { deferredFields: Record<string, (keyof TFrag)[]> } }
    ).__meta__?.deferredFields;

    if (!deferredFields) return true;

    const fragDef = fragmentNode.definitions[0] as FragmentDefinitionNode | undefined;
    const fragName = fragDef?.name?.value;

    const fields = (fragName && deferredFields[fragName]) || [];
    return fields.length > 0 && fields.every((field) => data && field in data);
}

