import uniqBy from 'lodash/uniqBy';
import { useMemo } from 'react';
import { useActiveChainId } from 'hooks/useActiveChainId';
import DEFAULT_TOKEN_LIST from '@/config/constants/tokenLists/pancake-default.tokenlist.json';
import UNSUPPORTED_TOKEN_LIST from '@/config/constants/tokenLists/pancake-unsupported.tokenlist.json';
import WARNING_TOKEN_LIST from '@/config/constants/tokenLists/pancake-warning.tokenlist.json';
import ONRAMP_TOKEN_LIST from '@/config/constants/tokenLists/pancake-supported-onramp-currency-list.json';
import { listsAtom } from './lists';
import { isAddress } from '@/utils';

type TokenAddressMap = TTokenAddressMap<ChainId>;

// use ordering of default list of lists to assign priority
function sortByListPriority(urlA: string, urlB: string) {
    const first = DEFAULT_LIST_OF_LISTS.includes(urlA)
        ? DEFAULT_LIST_OF_LISTS.indexOf(urlA)
        : Number.MAX_SAFE_INTEGER;
    const second = DEFAULT_LIST_OF_LISTS.includes(urlB)
        ? DEFAULT_LIST_OF_LISTS.indexOf(urlB)
        : Number.MAX_SAFE_INTEGER;

    // need reverse order to make sure mapping includes top priority last
    if (first < second) return 1;
    if (first > second) return -1;
    return 0;
}

function enumKeys<O extends object, K extends keyof O = keyof O>(obj: O): K[] {
    return Object.keys(obj).filter((k) => Number.isNaN(+k)) as K[];
}

// -------------------------------------
//   Selectors
// -------------------------------------
const selectorActiveUrlsAtom = atom((get) => get(listsAtom)?.activeListUrls ?? []);
export const selectorByUrlsAtom = atom((get) => get(listsAtom)?.byUrl ?? {});

const activeListUrlsAtom = atom((get) => {
    const urls = get(selectorActiveUrlsAtom);
    return urls?.filter((url) => !UNSUPPORTED_LIST_URLS.includes(url));
});

const combineTokenMapsWithDefault = (lists: ListsState['byUrl'], urls: string[]) => {
    const defaultTokenMap = listToTokenMap(DEFAULT_TOKEN_LIST as TokenList, 'address');
    if (!urls) return defaultTokenMap;
    return combineMaps(combineTokenMaps(lists, urls), defaultTokenMap);
};

const combineTokenMapsWithOnRamp = () => {
    const onRampTokens = listToTokenMap(ONRAMP_TOKEN_LIST as TokenList, 'symbol');
    return onRampTokens;
};

export const combinedCurrenciesMapFromActiveUrlsAtom = atom(() => {
    return combineTokenMapsWithOnRamp();
});

const combineTokenMaps = (lists: ListsState['byUrl'], urls: string[]): any => {
    if (!urls) return EMPTY_LIST;
    return (
        [...urls]
            // sort by priority so top priority goes last
            .sort(sortByListPriority)
            .reduce((allTokens, currentUrl) => {
                const current = lists[currentUrl]?.current;
                if (!current) return allTokens;
                try {
                    const newTokens = Object.assign(listToTokenMap(current, 'address'));
                    return combineMaps(allTokens, newTokens);
                } catch (error) {
                    console.error('Could not show token list due to error', error);
                    return allTokens;
                }
            }, EMPTY_LIST)
    );
};

export const combinedTokenMapFromActiveUrlsAtom = atom((get) => {
    const [selectorByUrls, selectorActiveUrls] = [
        get(selectorByUrlsAtom),
        get(selectorActiveUrlsAtom),
    ];
    return combineTokenMapsWithDefault(selectorByUrls, selectorActiveUrls);
});

const inactiveUrlAtom = atom((get) => {
    const [lists, urls] = [get(selectorByUrlsAtom), get(selectorActiveUrlsAtom)];
    return Object.keys(lists).filter(
        (url) => !urls?.includes(url) && !UNSUPPORTED_LIST_URLS.includes(url),
    );
});

export const combinedTokenMapFromInActiveUrlsAtom = atom((get) => {
    const [lists, inactiveUrl] = [get(selectorByUrlsAtom), get(inactiveUrlAtom)];
    return combineTokenMaps(lists, inactiveUrl);
});

export const combinedTokenMapFromOfficialsUrlsAtom = atom((get) => {
    const lists = get(selectorByUrlsAtom);
    return combineTokenMapsWithDefault(lists, OFFICIAL_LISTS);
});

export const tokenListFromOfficialsUrlsAtom = atom((get) => {
    const lists: ListsState['byUrl'] = get(selectorByUrlsAtom);

    const mergedTokenLists: TokenInfo[] = OFFICIAL_LISTS.reduce((acc, url) => {
        if (lists?.[url]?.current?.tokens) {
            acc.push(...(lists?.[url]?.current?.tokens || []));
        }
        return acc;
    }, []);

    const mergedList =
        mergedTokenLists.length > 0
            ? [...DEFAULT_TOKEN_LIST.tokens, ...mergedTokenLists]
            : DEFAULT_TOKEN_LIST.tokens;
    return mapValues(
        groupBy(
            uniqBy(mergedList, (tokenInfo) => `${tokenInfo.chainId}#${tokenInfo.address}`),
            'chainId',
        ),
        (tokenInfos) => keyBy(tokenInfos, 'address'),
    );
});

export const combinedTokenMapFromUnsupportedUrlsAtom = atom((get) => {
    const lists = get(selectorByUrlsAtom);
    // get hard coded unsupported tokens
    const localUnsupportedListMap = listToTokenMap(UNSUPPORTED_TOKEN_LIST, 'address');
    // get any loaded unsupported tokens
    const loadedUnsupportedListMap = combineTokenMaps(lists, UNSUPPORTED_LIST_URLS);

    return combineMaps(localUnsupportedListMap, loadedUnsupportedListMap);
});

export const combinedTokenMapFromWarningUrlsAtom = atom((get) => {
    const lists = get(selectorByUrlsAtom);
    // get hard coded unsupported tokens
    const localUnsupportedListMap = listToTokenMap(WARNING_TOKEN_LIST as TokenList, 'address');
    // get any loaded unsupported tokens
    const loadedUnsupportedListMap = combineTokenMaps(lists, WARNING_LIST_URLS);

    return combineMaps(localUnsupportedListMap, loadedUnsupportedListMap);
});
const listCache: WeakMap<TokenList, TokenAddressMap> | null =
    typeof WeakMap !== 'undefined' ? new WeakMap<TokenList, TokenAddressMap>() : null;

export function listToTokenMap(list: TokenList, key?: string): TokenAddressMap {
    const result = listCache?.get(list);
    if (result) return result;

    const tokenMap: WrappedTokenInfo[] = uniqBy(
        list.tokens,
        (tokenInfo: TokenInfo) => `${tokenInfo.chainId}#${tokenInfo.address}`,
    )
        .map((tokenInfo) => {
            const checksummedAddress = isAddress(tokenInfo.address);
            if (checksummedAddress) {
                return new WrappedTokenInfo({ ...tokenInfo, address: checksummedAddress });
            }
            return null;
        })
        .filter(Boolean);

    const groupedTokenMap: { [chainId: string]: WrappedTokenInfo[] } = groupBy(tokenMap, 'chainId');

    const tokenAddressMap = mapValues(groupedTokenMap, (tokenInfoList) =>
        mapValues(keyBy(tokenInfoList, key), (tokenInfo) => ({ token: tokenInfo, list })),
    ) as TokenAddressMap;

    // add chain id item if not exist
    enumKeys(ChainId).forEach((chainId) => {
        if (!(ChainId[chainId] in tokenAddressMap)) {
            Object.defineProperty(tokenAddressMap, ChainId[chainId], {
                value: {},
            });
        }
    });

    listCache?.set(list, tokenAddressMap);
    return tokenAddressMap;
}

// -------------------------------------
//   Hooks
// -------------------------------------
export function useAllLists(): {
    readonly [url: string]: {
        readonly current: TokenList | null;
        readonly pendingUpdate: TokenList | null;
        readonly loadingRequestId: string | null;
        readonly error: string | null;
    };
} {
    const { chainId } = useActiveChainId();

    const urls = useAtomValue(selectorByUrlsAtom);

    return useMemo(
        () => _pickBy(urls, (_, url) => MULTI_CHAIN_LIST_URLS[chainId]?.includes(url)),
        [chainId, urls],
    );
}

function combineMaps(map1: TokenAddressMap, map2: TokenAddressMap): TokenAddressMap {
    const combinedMap: TokenAddressMap = {} as TokenAddressMap;
    for (const chainId of enumValues(ChainId)) {
        combinedMap[chainId as number] = { ...map1[chainId], ...map2[chainId] };
    }
    return combinedMap;
}

// filter out unsupported lists
export function useActiveListUrls(): string[] | undefined {
    const { chainId } = useActiveChainId();
    const urls = useAtomValue(activeListUrlsAtom);

    return useMemo(
        () => urls.filter((url) => MULTI_CHAIN_LIST_URLS[chainId]?.includes(url)),
        [urls, chainId],
    );
}

export function useInactiveListUrls() {
    return useAtomValue(inactiveUrlAtom);
}

// get all the tokens from active lists, combine with local default tokens
export function useCombinedActiveList(): TokenAddressMap {
    const activeTokens = useAtomValue(combinedTokenMapFromActiveUrlsAtom);
    return activeTokens;
}

// all tokens from inactive lists
export function useCombinedInactiveList(): TokenAddressMap {
    return useAtomValue(combinedTokenMapFromInActiveUrlsAtom);
}

// list of tokens not supported on interface, used to show warnings and prevent swaps and adds
export function useUnsupportedTokenList(): TokenAddressMap {
    return useAtomValue(combinedTokenMapFromUnsupportedUrlsAtom);
}

// list of warning tokens on interface, used to show warnings and prevent adds
export function useWarningTokenList(): TokenAddressMap {
    return useAtomValue(combinedTokenMapFromWarningUrlsAtom);
}

export function useIsListActive(url: string): boolean {
    const activeListUrls = useActiveListUrls();
    return useMemo(() => Boolean(activeListUrls?.includes(url)), [activeListUrls, url]);
}

import { createListsAtom, createTokenListReducer, NEW_LIST_STATE } from '@dapp/token-lists/react';
import {
    DEFAULT_ACTIVE_LIST_URLS,
    DEFAULT_LIST_OF_LISTS,
    UNSUPPORTED_LIST_URLS,
} from '@/config/constants/lists';

export const initialState = {
    lastInitializedDefaultListOfLists: DEFAULT_LIST_OF_LISTS,
    byUrl: {
        ...DEFAULT_LIST_OF_LISTS.concat(...UNSUPPORTED_LIST_URLS).reduce((memo, listUrl) => {
            memo[listUrl] = NEW_LIST_STATE;
            return memo;
        }, {}),
    },
    activeListUrls: DEFAULT_ACTIVE_LIST_URLS,
};

const listReducer = createTokenListReducer(
    initialState,
    DEFAULT_LIST_OF_LISTS,
    DEFAULT_ACTIVE_LIST_URLS,
);

export const { listsAtom, useListState, useListStateReady } = createListsAtom(
    'listv4',
    listReducer,
    initialState,
);

import { getVersionUpgrade, VersionUpgrade } from '@dapp/token-lists';
import { acceptListUpdate, updateListVersion, useFetchListCallback } from '@dapp/token-lists/react';
import { EXCHANGE_PAGE_PATHS } from 'config/constants/exchange';
import { UNSUPPORTED_LIST_URLS } from 'config/constants/lists';
import { usePublicClient } from 'wagmi';
import { useActiveChainId } from 'hooks/useActiveChainId';
import { useRouter } from 'next/router';
import { useEffect, useMemo } from 'react';
import { useAllLists } from '@/state/lists/hooks';
import useSWRImmutable from 'swr/immutable';
import { useActiveListUrls } from './hooks';
import { useListState, useListStateReady, initialState } from './lists';

export default function Updater(): null {
    const { chainId } = useActiveChainId();
    const provider = usePublicClient({ chainId });

    const [listState, dispatch] = useListState();
    const router = useRouter();
    const includeListUpdater = useMemo(() => {
        return EXCHANGE_PAGE_PATHS.some((item) => {
            return router.pathname.startsWith(item);
        });
    }, [router.pathname]);

    const isReady = useListStateReady();

    // get all loaded lists, and the active urls
    const lists = useAllLists();
    const activeListUrls = useActiveListUrls();

    useEffect(() => {
        if (isReady) {
            dispatch(updateListVersion());
        }
    }, [dispatch, isReady]);

    const fetchList = useFetchListCallback(dispatch);

    // whenever a list is not loaded and not loading, try again to load it
    useSWRImmutable(isReady && ['first-fetch-token-list', lists], () => {
        Object.keys(lists).forEach((listUrl) => {
            const list = lists[listUrl];
            if (!list.current && !list.loadingRequestId && !list.error) {
                fetchList(listUrl).catch((error) =>
                    console.debug('list added fetching error', error),
                );
            }
        });
    });

    useSWRImmutable(
        includeListUpdater && isReady && listState !== initialState ? ['token-list'] : null,
        async () => {
            return Promise.all(
                Object.keys(lists).map((url) =>
                    fetchList(url).catch((error) =>
                        console.debug('interval list fetching error', error),
                    ),
                ),
            );
        },
        {
            dedupingInterval: 1000 * 60 * 10,
            refreshInterval: 1000 * 60 * 10,
        },
    );

    // if any lists from unsupported lists are loaded, check them too (in case new updates since last visit)
    useEffect(() => {
        if (isReady) {
            Object.keys(UNSUPPORTED_LIST_URLS).forEach((listUrl) => {
                const list = lists[listUrl];
                if (!list || (!list.current && !list.loadingRequestId && !list.error)) {
                    fetchList(listUrl).catch((error) =>
                        console.debug('list added fetching error', error),
                    );
                }
            });
        }
    }, [fetchList, provider, lists, isReady]);

    // automatically update lists if versions are minor/patch
    useEffect(() => {
        if (!isReady) return;
        Object.keys(lists).forEach((listUrl) => {
            const list = lists[listUrl];
            if (list.current && list.pendingUpdate) {
                const bump = getVersionUpgrade(list.current.version, list.pendingUpdate.version);
                // eslint-disable-next-line default-case
                switch (bump) {
                    case VersionUpgrade.NONE:
                        throw new Error('unexpected no version bump');
                    // update any active or inactive lists
                    case VersionUpgrade.PATCH:
                    case VersionUpgrade.MINOR:
                    case VersionUpgrade.MAJOR:
                        dispatch(acceptListUpdate(listUrl));
                }
            }
        });
    }, [dispatch, lists, activeListUrls, isReady]);

    return null;
}

import { createAction } from '@reduxjs/toolkit';

export enum Field {
    CURRENCY_A = 'CURRENCY_A',
    CURRENCY_B = 'CURRENCY_B',
}

export const typeInput = createAction<{ field: Field; typedValue: string; noLiquidity: boolean }>(
    'mint/typeInputMint',
);
export const resetMintState = createAction<void>('mint/resetMintState');

import { Currency, CurrencyAmount, Pair, Percent, Price, Token } from '@dapp/sdk';
import { BIG_INT_ZERO } from 'config/constants/exchange';
import { PairState, useV2Pair } from 'hooks/usePairs';
import useTotalSupply from 'hooks/useTotalSupply';
import { useCallback, useMemo } from 'react';
import tryParseAmount from '@dapp/utils/tryParseAmount';
import { useAddLiquidityV2FormDispatch, useAddLiquidityV2FormState } from 'state/mint/reducer';
import { useAccount } from 'wagmi';
import { useCurrencyBalances } from '../wallet/hooks';
import { Field, typeInput } from './actions';

export function useMintActionHandlers(noLiquidity: boolean | undefined): {
    onFieldAInput: (typedValue: string) => void;
    onFieldBInput: (typedValue: string) => void;
} {
    const dispatch = useAddLiquidityV2FormDispatch();

    const onFieldAInput = useCallback(
        (typedValue: string) => {
            dispatch(
                typeInput({
                    field: Field.CURRENCY_A,
                    typedValue,
                    noLiquidity: noLiquidity === true,
                }),
            );
        },
        [dispatch, noLiquidity],
    );
    const onFieldBInput = useCallback(
        (typedValue: string) => {
            dispatch(
                typeInput({
                    field: Field.CURRENCY_B,
                    typedValue,
                    noLiquidity: noLiquidity === true,
                }),
            );
        },
        [dispatch, noLiquidity],
    );

    return {
        onFieldAInput,
        onFieldBInput,
    };
}

export function useDerivedMintInfo(
    currencyA: Currency | undefined,
    currencyB: Currency | undefined,
): {
    isOneWeiAttack?: boolean;
    dependentField: Field;
    currencies: { [field in Field]?: Currency };
    pair?: Pair | null;
    pairState: PairState;
    currencyBalances: { [field in Field]?: CurrencyAmount<Currency> };
    parsedAmounts: { [field in Field]?: CurrencyAmount<Currency> };
    price?: Price<Currency, Currency>;
    noLiquidity?: boolean;
    liquidityMinted?: CurrencyAmount<Token>;
    poolTokenPercentage?: Percent;
    error?: string;
    addError?: string;
} {
    const { address: account } = useAccount();

    const { independentField, typedValue, otherTypedValue } = useAddLiquidityV2FormState();

    const dependentField =
        independentField === Field.CURRENCY_A ? Field.CURRENCY_B : Field.CURRENCY_A;

    // tokens
    const currencies: { [field in Field]?: Currency } = useMemo(
        () => ({
            [Field.CURRENCY_A]: currencyA ?? undefined,
            [Field.CURRENCY_B]: currencyB ?? undefined,
        }),
        [currencyA, currencyB],
    );

    // pair
    const [pairState, pair] = useV2Pair(currencies[Field.CURRENCY_A], currencies[Field.CURRENCY_B]);

    const totalSupply = useTotalSupply(pair?.liquidityToken);

    const isOneWeiAttack = useMemo(
        () =>
            Boolean(
                pairState === PairState.EXISTS &&
                    totalSupply &&
                    totalSupply.quotient === BIG_INT_ZERO &&
                    ((pair.reserve0.quotient > BIG_INT_ZERO &&
                        pair.reserve1.quotient === BIG_INT_ZERO) ||
                        (pair.reserve1.quotient > BIG_INT_ZERO &&
                            pair.reserve0.quotient === BIG_INT_ZERO)),
            ),
        [pairState, totalSupply, pair],
    );

    const noLiquidity: boolean =
        pairState === PairState.NOT_EXISTS ||
        Boolean(
            pairState === PairState.EXISTS &&
                pair &&
                pair.reserve0.quotient === BIG_INT_ZERO &&
                pair.reserve1.quotient === BIG_INT_ZERO,
        ) ||
        isOneWeiAttack;

    // balances
    const balances = useCurrencyBalances(
        account ?? undefined,
        useMemo(() => [currencies[Field.CURRENCY_A], currencies[Field.CURRENCY_B]], [currencies]),
    );
    const currencyBalances: { [field in Field]?: CurrencyAmount<Currency> } = {
        [Field.CURRENCY_A]: balances[0],
        [Field.CURRENCY_B]: balances[1],
    };

    // amounts
    const independentAmount: CurrencyAmount<Currency> | undefined = tryParseAmount(
        typedValue,
        currencies[independentField],
    );
    const dependentAmount: CurrencyAmount<Currency> | undefined = useMemo(() => {
        if (noLiquidity) {
            if (otherTypedValue && currencies[dependentField]) {
                return tryParseAmount(otherTypedValue, currencies[dependentField]);
            }
            return undefined;
        }
        if (independentAmount) {
            // we wrap the currencies just to get the price in terms of the other token
            const wrappedIndependentAmount = independentAmount?.wrapped;
            const [tokenA, tokenB] = [currencyA?.wrapped, currencyB?.wrapped];
            if (tokenA && tokenB && wrappedIndependentAmount && pair) {
                const dependentCurrency =
                    dependentField === Field.CURRENCY_B ? currencyB : currencyA;
                const dependentTokenAmount =
                    dependentField === Field.CURRENCY_B
                        ? pair.priceOf(tokenA).quote(wrappedIndependentAmount)
                        : pair.priceOf(tokenB).quote(wrappedIndependentAmount);
                return dependentCurrency?.isNative
                    ? CurrencyAmount.fromRawAmount(dependentCurrency, dependentTokenAmount.quotient)
                    : dependentTokenAmount;
            }
            return undefined;
        }
        return undefined;
    }, [
        noLiquidity,
        otherTypedValue,
        currencies,
        dependentField,
        independentAmount,
        currencyA,
        currencyB,
        pair,
    ]);

    const parsedAmounts: { [field in Field]: CurrencyAmount<Currency> | undefined } = useMemo(
        () => ({
            [Field.CURRENCY_A]:
                independentField === Field.CURRENCY_A ? independentAmount : dependentAmount,
            [Field.CURRENCY_B]:
                independentField === Field.CURRENCY_A ? dependentAmount : independentAmount,
        }),
        [dependentAmount, independentAmount, independentField],
    );

    const price = useMemo(() => {
        if (noLiquidity) {
            const { [Field.CURRENCY_A]: currencyAAmount, [Field.CURRENCY_B]: currencyBAmount } =
                parsedAmounts;
            if (currencyAAmount && currencyBAmount) {
                return new Price(
                    currencyAAmount.currency,
                    currencyBAmount.currency,
                    currencyAAmount.quotient,
                    currencyBAmount.quotient,
                );
            }
            return undefined;
        }
        if (
            !pair ||
            pair.reserve0.quotient === BIG_INT_ZERO ||
            pair.reserve1.quotient === BIG_INT_ZERO
        ) {
            return undefined;
        }
        const wrappedCurrencyA = currencyA?.wrapped;
        return wrappedCurrencyA ? pair.priceOf(wrappedCurrencyA) : undefined;
    }, [currencyA, noLiquidity, pair, parsedAmounts]);

    // liquidity minted
    const liquidityMinted = useMemo(() => {
        const { [Field.CURRENCY_A]: currencyAAmount, [Field.CURRENCY_B]: currencyBAmount } =
            parsedAmounts;
        const [tokenAmountA, tokenAmountB] = [currencyAAmount?.wrapped, currencyBAmount?.wrapped];
        if (pair && totalSupply && tokenAmountA && tokenAmountB) {
            try {
                return pair.getLiquidityMinted(totalSupply, tokenAmountA, tokenAmountB);
            } catch (error) {
                console.error(error);
                return undefined;
            }
        }
        return undefined;
    }, [parsedAmounts, pair, totalSupply]);

    const poolTokenPercentage = useMemo(() => {
        if (liquidityMinted && totalSupply) {
            return new Percent(liquidityMinted.quotient, totalSupply.add(liquidityMinted).quotient);
        }
        return undefined;
    }, [liquidityMinted, totalSupply]);

    let error: string | undefined;
    let addError: string | undefined;
    if (!account) {
        error = 'Connect Wallet';
    }

    if (pairState === PairState.INVALID) {
        error = error ?? 'Choose a valid pair';
    }

    const { [Field.CURRENCY_A]: currencyAAmount, [Field.CURRENCY_B]: currencyBAmount } =
        parsedAmounts;

    if (
        currencyAAmount &&
        currencyBAmount &&
        currencyBalances?.[Field.CURRENCY_A]?.equalTo(0) &&
        currencyBalances?.[Field.CURRENCY_B]?.equalTo(0)
    ) {
        error = error ?? 'No token balance';
    }

    if (!parsedAmounts[Field.CURRENCY_A] || !parsedAmounts[Field.CURRENCY_B]) {
        addError = 'Enter an amount';
    }

    if (currencyAAmount && currencyBalances?.[Field.CURRENCY_A]?.lessThan(currencyAAmount)) {
        addError = `Insufficient ${currencies[Field.CURRENCY_A]?.symbol} balance`;
    }

    if (currencyBAmount && currencyBalances?.[Field.CURRENCY_B]?.lessThan(currencyBAmount)) {
        addError = 'Insufficient ${currencies[Field.CURRENCY_B]?.symbol }} balance';
    }

    if (isOneWeiAttack) {
        addError = 'Invalid Pair';
    }

    return {
        isOneWeiAttack,
        dependentField,
        currencies,
        pair,
        pairState,
        currencyBalances,
        parsedAmounts,
        price,
        noLiquidity,
        liquidityMinted,
        poolTokenPercentage,
        error,
        addError,
    };
}

import { createStore, Store } from 'redux';

import { Field, typeInput } from './actions';
import { MintState, reducer } from './reducer';

describe('mint reducer', () => {
    let store: Store<MintState>;

    beforeEach(() => {
        store = createStore(reducer, {
            independentField: Field.CURRENCY_A,
            typedValue: '',
            otherTypedValue: '',
        });
    });

    describe('typeInput', () => {
        it('sets typed value', () => {
            store.dispatch(
                typeInput({ field: Field.CURRENCY_A, typedValue: '1.0', noLiquidity: false }),
            );
            expect(store.getState()).toEqual({
                independentField: Field.CURRENCY_A,
                typedValue: '1.0',
                otherTypedValue: '',
            });
        });
        it('clears other value', () => {
            store.dispatch(
                typeInput({ field: Field.CURRENCY_A, typedValue: '1.0', noLiquidity: false }),
            );
            store.dispatch(
                typeInput({ field: Field.CURRENCY_B, typedValue: '1.0', noLiquidity: false }),
            );
            expect(store.getState()).toEqual({
                independentField: Field.CURRENCY_B,
                typedValue: '1.0',
                otherTypedValue: '',
            });
        });
    });
});

import { createContext, useContext } from 'react';
import { createReducer } from '@reduxjs/toolkit';
import { atomWithReducer } from 'jotai/utils';
import { useAtomValue, useSetAtom } from 'jotai';
import { Field, resetMintState, typeInput } from './actions';

export interface MintState {
    readonly independentField: Field;
    readonly typedValue: string;
    readonly otherTypedValue: string; // for the case when there's no liquidity
}

const initialState: MintState = {
    independentField: Field.CURRENCY_A,
    typedValue: '',
    otherTypedValue: '',
};

export const reducer = createReducer<MintState>(initialState, (builder) =>
    builder
        .addCase(resetMintState, () => initialState)
        .addCase(typeInput, (state, { payload: { field, typedValue, noLiquidity } }) => {
            if (noLiquidity) {
                // they're typing into the field they've last typed in
                if (field === state.independentField) {
                    return {
                        ...state,
                        independentField: field,
                        typedValue,
                    };
                }
                // they're typing into a new field, store the other value

                return {
                    ...state,
                    independentField: field,
                    typedValue,
                    otherTypedValue: state.typedValue,
                };
            }
            return {
                ...state,
                independentField: field,
                typedValue,
                otherTypedValue: '',
            };
        }),
);

