import { createReducer } from '@reduxjs/toolkit';
import { atomWithReducer } from 'jotai/utils';
import {
    addMulticallListeners,
    errorFetchingMulticallResults,
    fetchingMulticallResults,
    removeMulticallListeners,
    toCallKey,
    updateMulticallResults,
} from './actions';

export interface MulticallState {
    callListeners?: {
        // on a per-chain basis
        [chainId: number]: {
            // stores for each call key the listeners' preferences
            [callKey: string]: {
                // stores how many listeners there are per each blocks per fetch preference
                [blocksPerFetch: number]: number;
            };
        };
    };

    callResults: {
        [chainId: number]: {
            [callKey: string]: {
                data?: string | null;
                blockNumber?: number;
                fetchingBlockNumber?: number;
            };
        };
    };
}

const initialState: MulticallState = {
    callResults: {},
};

export const multicallReducer = createReducer(initialState, (builder) =>
    builder
        .addCase(
            addMulticallListeners,
            (state, { payload: { calls, chainId, options: { blocksPerFetch = 1 } = {} } }) => {
                const listeners: MulticallState['callListeners'] = state.callListeners
                    ? state.callListeners
                    : (state.callListeners = {});

                listeners[chainId] = listeners[chainId] ?? {};
                calls.forEach((call) => {
                    const callKey = toCallKey(call);
                    listeners[chainId][callKey] = listeners[chainId][callKey] ?? {};
                    listeners[chainId][callKey][blocksPerFetch] =
                        (listeners[chainId][callKey][blocksPerFetch] ?? 0) + 1;
                });
            },
        )
        .addCase(
            removeMulticallListeners,
            (state, { payload: { chainId, calls, options: { blocksPerFetch = 1 } = {} } }) => {
                const listeners: MulticallState['callListeners'] = state.callListeners
                    ? state.callListeners
                    : (state.callListeners = {});

                if (!listeners[chainId]) return;
                calls.forEach((call) => {
                    const callKey = toCallKey(call);
                    if (!listeners[chainId][callKey]) return;
                    if (!listeners[chainId][callKey][blocksPerFetch]) return;

                    if (listeners[chainId][callKey][blocksPerFetch] === 1) {
                        delete listeners[chainId][callKey][blocksPerFetch];
                    } else {
                        listeners[chainId][callKey][blocksPerFetch]--;
                    }
                });
            },
        )
        .addCase(
            fetchingMulticallResults,
            (state, { payload: { chainId, fetchingBlockNumber, calls } }) => {
                state.callResults[chainId] = state.callResults[chainId] ?? {};
                calls.forEach((call) => {
                    const callKey = toCallKey(call);
                    const current = state.callResults[chainId][callKey];

                    console.log({ currentCall: current, callKey, chainId, state });
                    if (!current) {
                        state.callResults[chainId][callKey] = {
                            fetchingBlockNumber,
                        };
                    } else {
                        if ((current.fetchingBlockNumber ?? 0) >= fetchingBlockNumber) return;
                        state.callResults[chainId][callKey].fetchingBlockNumber =
                            fetchingBlockNumber;
                    }
                });
            },
        )
        .addCase(
            errorFetchingMulticallResults,
            (state, { payload: { fetchingBlockNumber, chainId, calls } }) => {
                state.callResults[chainId] = state.callResults[chainId] ?? {};
                calls.forEach((call) => {
                    const callKey = toCallKey(call);
                    const current = state.callResults[chainId][callKey];
                    if (!current) return; // only should be dispatched if we are already fetching
                    if (current.fetchingBlockNumber === fetchingBlockNumber) {
                        delete current.fetchingBlockNumber;
                        current.data = null;
                        current.blockNumber = fetchingBlockNumber;
                    }
                });
            },
        )
        .addCase(
            updateMulticallResults,
            (state, { payload: { chainId, results, blockNumber } }) => {
                state.callResults[chainId] = state.callResults[chainId] ?? {};
                Object.keys(results).forEach((callKey) => {
                    const current = state.callResults[chainId][callKey];
                    if ((current?.blockNumber ?? 0) > blockNumber) return;
                    state.callResults[chainId][callKey] = {
                        data: results[callKey],
                        blockNumber,
                    };
                });
            },
        ),
);

export const multicallReducerAtom = atomWithReducer(initialState, multicallReducer);

import { vi, describe, it } from 'vitest';
import { retry, RetryableError } from './retry';

describe.concurrent('retry', () => {
    beforeEach(() => {
        vi.spyOn(console, 'error').mockImplementation(() => {
            //
        });
    });
    function makeFn<T>(fails: number, result: T, retryable = true): () => Promise<T> {
        return async () => {
            if (fails > 0) {
                // eslint-disable-next-line no-param-reassign
                fails--;
                throw retryable ? new RetryableError('failure') : new Error('bad failure');
            }
            return result;
        };
    }

    it('fails for non-retryable error', async () => {
        await expect(
            retry(makeFn(1, 'abc', false), { n: 3, maxWait: 0, minWait: 0 }).promise,
        ).rejects.toThrow('bad failure');
    });

    it('works after one fail', async () => {
        await expect(
            retry(makeFn(1, 'abc'), { n: 3, maxWait: 0, minWait: 0 }).promise,
        ).resolves.toEqual('abc');
    });

    it('works after two fails', async () => {
        await expect(
            retry(makeFn(2, 'abc'), { n: 3, maxWait: 0, minWait: 0 }).promise,
        ).resolves.toEqual('abc');
    });

    it('throws if too many fails', async () => {
        await expect(
            retry(makeFn(4, 'abc'), { n: 3, maxWait: 0, minWait: 0 }).promise,
        ).rejects.toThrow('failure');
    });

    it('cancel causes promise to reject', async () => {
        const { promise, cancel } = retry(makeFn(2, 'abc'), { n: 3, minWait: 100, maxWait: 100 });
        cancel();
        await expect(promise).rejects.toThrow('Cancelled');
    });

    it('cancel no-op after complete', async () => {
        const { promise, cancel } = retry(makeFn(0, 'abc'), { n: 3, minWait: 100, maxWait: 100 });
        // defer
        setTimeout(cancel, 0);
        await expect(promise).resolves.toEqual('abc');
    });

    async function checkTime(fn: () => Promise<any>, min: number, max: number) {
        const time = Date.now();
        await fn();
        const diff = Date.now() - time;
        expect(diff).toBeGreaterThanOrEqual(min);
        expect(diff).toBeLessThanOrEqual(max);
    }

    it('waits random amount of time between min and max', async () => {
        const promises = [];
        for (let i = 0; i < 10; i++) {
            promises.push(
                checkTime(
                    () =>
                        expect(
                            retry(makeFn(4, 'abc'), { n: 3, maxWait: 100, minWait: 50 }).promise,
                        ).rejects.toThrow('failure'),
                    150,
                    400,
                ),
            );
        }
        await Promise.all(promises);
    });
});

/* eslint-disable */

function wait(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

function waitRandom(min: number, max: number): Promise<void> {
    return wait(min + Math.round(Math.random() * Math.max(0, max - min)));
}

/**
 * This error is thrown if the function is cancelled before completing
 */
export class CancelledError extends Error {
    constructor() {
        super('Cancelled');
    }
}

/**
 * Throw this error if the function should retry
 */
export class RetryableError extends Error {}

/**
 * Retries the function that returns the promise until the promise successfully resolves up to n retries
 * @param fn function to retry
 * @param n how many times to retry
 * @param minWait min wait between retries in ms
 * @param maxWait max wait between retries in ms
 */
export function retry<T>(
    fn: () => Promise<T>,
    { n, minWait, maxWait }: { n: number; minWait: number; maxWait: number },
): { promise: Promise<T>; cancel: () => void } {
    let completed = false;
    let rejectCancelled: (error: Error) => void;
    const promise = new Promise<T>(async (resolve, reject) => {
        rejectCancelled = reject;
        while (true) {
            let result: T;
            try {
                result = await fn();
                if (!completed) {
                    resolve(result);
                    completed = true;
                }
                break;
            } catch (error) {
                if (completed) {
                    break;
                }
                if (n <= 0 || !(error instanceof RetryableError)) {
                    console.error(error);
                    reject(error);
                    completed = true;
                    break;
                }
                n--;
            }
            await waitRandom(minWait, maxWait);
        }
    });
    return {
        promise,
        cancel: () => {
            if (completed) return;
            completed = true;
            rejectCancelled(new CancelledError());
        },
    };
}

