import { BigintIsh, ZERO, ONE } from '@dapp/sdk'
import invariant from 'tiny-invariant'

interface Params {
  amplifier: BigintIsh
  balances: BigintIsh[]
}

/**
 * Calculate the constant D of Curve AMM formula
 * @see https://classic.curve.fi/files/stableswap-paper.pdf
 */
export function getD({ amplifier, balances }: Params): bigint {
  const numOfCoins = balances.length
  invariant(numOfCoins > 1, 'To get constant D, pool should have at least two coins.')

  const sum = balances.reduce<bigint>((s, cur) => s + BigInt(cur), ZERO)
  if (sum === ZERO) {
    return ZERO
  }

  const n = BigInt(numOfCoins)
  // Equality with the precision of 1
  const precision = ONE
  // The amplifier is actually An^n-1, so we only times n here
  const ann = BigInt(amplifier) * n
  let dPrev = ZERO
  let d = sum
  for (let i = 0; i < 255; i += 1) {
    let dp = d
    for (const b of balances) {
      dp = (dp * d) / (BigInt(b) * n + 1n)
    }
    dPrev = d
    d = ((ann * sum + dp * n) * d) / ((ann - ONE) * d + (n + ONE) * dp)

    if (d > dPrev && d - dPrev <= precision) {
      break
    }

    if (d <= dPrev && dPrev - d <= precision) {
      break
    }
  }

  return d
}

interface GetYParams {
  amplifier: BigintIsh
  balances: BigintIsh[]
  // The index of the base token
  i: number
  // The index of the swap target token
  j: number
  // The amount of token i that user deposit
  x: BigintIsh
}

/**
 * Calculate the expected token amount y after user deposit
 * @see https://classic.curve.fi/files/stableswap-paper.pdf
 */
export function getY({ amplifier, balances, i, j, x }: GetYParams): bigint {
  const numOfCoins = balances.length
  invariant(numOfCoins > 1, 'To get y, pool should have at least two coins.')
  invariant(i !== j && i >= 0 && j >= 0 && i < numOfCoins && j < numOfCoins, `Invalid i: ${i} and j: ${j}`)

  const n = BigInt(numOfCoins)
  const d = getD({ amplifier, balances })
  let sum = ZERO
  let c = d
  // The amplifier is actually An^n-1, so we only times n here
  const ann = BigInt(amplifier) * n
  for (const [index, b] of balances.entries()) {
    if (index === j) {
      // eslint-disable-next-line no-continue
      continue
    }
    let balanceAfterDeposit = BigInt(b)
    if (index === i) {
      balanceAfterDeposit += BigInt(x)
    }

    invariant(balanceAfterDeposit > ZERO, 'Insufficient liquidity')

    sum += balanceAfterDeposit
    c = (c * d) / (balanceAfterDeposit * n)
  }
  c = (c * d) / (ann * n)
  const b = sum + d / ann

  // Equality with the precision of 1
  const precision = ONE
  let yPrev = ZERO
  let y = d
  for (let k = 0; k < 255; k += 1) {
    yPrev = y
    y = (y * y + c) / (2n * y + b - d)

    if (y > yPrev && y - yPrev <= precision) {
      break
    }

    if (y <= yPrev && yPrev - y <= precision) {
      break
    }
  }

  return y
}

import { BigintIsh, CurrencyAmount, Currency, ZERO, Percent } from '@dapp/sdk'
import invariant from 'tiny-invariant'

import { getD } from './amm'
import { getRawAmount } from './utils'

export interface GetLPOutputParams {
  amplifier: BigintIsh
  // Token balances of the stable pool
  balances: CurrencyAmount<Currency>[]
  // User input amounts
  amounts: CurrencyAmount<Currency>[]
  // Total supply of LP token
  totalSupply: CurrencyAmount<Currency>
  // Fee of adding liquidity
  fee: Percent
}

export function getLPOutput({
  amplifier,
  balances,
  totalSupply,
  amounts,
  fee,
}: GetLPOutputParams): CurrencyAmount<Currency> {
  const lpToken = totalSupply.currency
  const lpTotalSupply = totalSupply.quotient
  // No liquidity in pool
  if (lpTotalSupply === ZERO || !balances.length || balances.every((b) => b.quotient === ZERO)) {
    const d = getD({ amplifier, balances: amounts.map(getRawAmount) })
    return CurrencyAmount.fromRawAmount(lpToken, d)
  }

  const currentBalances: bigint[] = []
  const newBalances: bigint[] = []
  for (const [i, balance] of balances.entries()) {
    const amount = amounts[i] || CurrencyAmount.fromRawAmount(balance.currency, 0)
    invariant(
      amount.currency.wrapped.equals(balance.currency.wrapped),
      'User input currency should be the same as pool balance currency.',
    )
    const balanceRaw = getRawAmount(balance)
    const amountRaw = getRawAmount(amount)
    currentBalances.push(balanceRaw)
    newBalances.push(balanceRaw + amountRaw)
  }

  const d0 = getD({ amplifier, balances: currentBalances })
  const d1 = getD({ amplifier, balances: newBalances })
  invariant(d1 >= d0, 'D1 should be greater than or equal than d0.')

  const isFirstSupply = lpTotalSupply <= ZERO
  if (isFirstSupply) {
    return CurrencyAmount.fromRawAmount(totalSupply.currency, d1)
  }

  const n = currentBalances.length
  const eachTokenFee = fee.multiply(n).divide(4 * (n - 1))

  let d2 = d1
  for (const [i, b] of currentBalances.entries()) {
    const idealBalance = (d1 * b) / d0
    let diff = ZERO
    if (idealBalance > newBalances[i]) {
      diff = idealBalance - newBalances[i]
    } else {
      diff = newBalances[i] - idealBalance
    }
    const feeAmount = eachTokenFee.multiply(diff).quotient
    // eslint-disable-next-line operator-assignment
    newBalances[i] = newBalances[i] - feeAmount
  }
  d2 = getD({ amplifier, balances: newBalances })

  const expectedMintLP = (lpTotalSupply * (d2 - d0)) / d0
  return CurrencyAmount.fromRawAmount(totalSupply.currency, expectedMintLP)
}

import { CurrencyAmount, Currency, Percent } from '@dapp/sdk'

import { getLPOutput, GetLPOutputParams } from './getLPOutput'

export function getLPOutputWithoutFee(params: Omit<GetLPOutputParams, 'fee'>): CurrencyAmount<Currency> {
  return getLPOutput({ ...params, fee: new Percent(0) })
}

import { describe, it, expect } from 'vitest'
import { CurrencyAmount, Percent } from '@dapp/sdk'
import { bscTokens } from '@dapp/tokens'

import { getSwapOutput, getSwapInput } from './getSwapOutput'

describe('getSwapOutput', () => {
  it('Exact output should match exact input', () => {
    const params = {
      amplifier: 1000,
      balances: [
        CurrencyAmount.fromRawAmount(bscTokens.usdt, '45783656091242964455008335'),
        CurrencyAmount.fromRawAmount(bscTokens.busd, '67779343437455288075126268'),
      ],
      outputCurrency: bscTokens.busd,
      amount: CurrencyAmount.fromRawAmount(bscTokens.usdt, '2000000000000000000'),
      fee: new Percent('15000000', '10000000000'),
    }
    const exactIn = getSwapOutput(params)
    expect(exactIn.currency).toBe(bscTokens.busd)
    expect(exactIn.quotient).toEqual(1997834290490693375n)

    const exactOut = getSwapInput({
      ...params,
      outputCurrency: bscTokens.usdt,
      amount: CurrencyAmount.fromRawAmount(bscTokens.busd, '1997834290490693375'),
    })
    expect(exactOut.currency).toBe(bscTokens.usdt)
    expect(exactOut.quotient).toEqual(2000000000000000000n)
  })
})

import { BigintIsh, CurrencyAmount, Currency, Percent, ZERO, ONE_HUNDRED_PERCENT } from '@dapp/sdk'
import invariant from 'tiny-invariant'

import { getY } from './amm'
import { getRawAmount, parseAmount } from './utils'

export interface GetSwapOutputParams {
  amplifier: BigintIsh
  // Token balances of the stable pool
  balances: CurrencyAmount<Currency>[]
  // User input amount
  amount: CurrencyAmount<Currency>
  // The currency user want to swap to
  outputCurrency: Currency
  // Fee of swapping
  fee: Percent
}

export function getSwapOutput({
  amplifier,
  balances: balanceAmounts,
  outputCurrency,
  amount,
  fee,
}: GetSwapOutputParams): CurrencyAmount<Currency> {
  const validateAmountOut = (a: CurrencyAmount<Currency>) =>
    invariant(!a.lessThan(ZERO), 'Insufficient liquidity to perform the swap')

  let i: number | null = null
  let j: number | null = null
  const balances: bigint[] = []
  for (const [index, b] of balanceAmounts.entries()) {
    balances.push(getRawAmount(b))
    if (b.currency.wrapped.equals(amount.currency.wrapped)) {
      i = index
      // eslint-disable-next-line no-continue
      continue
    }
    if (b.currency.wrapped.equals(outputCurrency.wrapped)) {
      j = index
      // eslint-disable-next-line no-continue
      continue
    }
  }

  invariant(
    i !== null && j !== null && i !== j,
    'Input currency or output currency does not match currencies of token balances.',
  )

  // Exact output
  if (amount.quotient < ZERO) {
    const x = ONE_HUNDRED_PERCENT.subtract(fee).invert().multiply(getRawAmount(amount)).quotient
    const y = getY({ amplifier, balances, i, j, x })
    const dy = y - balances[j]
    const amountOut = parseAmount(outputCurrency, dy)
    validateAmountOut(amountOut)
    return amountOut
  }

  const y = getY({ amplifier, balances, i, j, x: getRawAmount(amount) })
  const dy = balances[j] - y
  const feeAmount = fee.multiply(dy).quotient
  const amountOut = parseAmount(outputCurrency, dy - feeAmount)
  validateAmountOut(amountOut)
  return amountOut
}

export function getSwapOutputWithoutFee(params: Omit<GetSwapOutputParams, 'fee'>): CurrencyAmount<Currency> {
  return getSwapOutput({ ...params, fee: new Percent(0) })
}

export function getSwapInput({ amount, ...rest }: GetSwapOutputParams) {
  return getSwapOutput({
    ...rest,
    amount: CurrencyAmount.fromRawAmount(amount.currency, -amount.quotient),
  })
}

export function getSwapInputWithtouFee(params: Omit<GetSwapOutputParams, 'fee'>) {
  return getSwapInput({ ...params, fee: new Percent(0) })
}

import { CurrencyAmount, Currency } from '@dapp/sdk'

const PRECISION = 10n ** 18n

export const getRawAmount = (amount: CurrencyAmount<Currency>) => {
  return (amount.quotient * PRECISION) / 10n ** BigInt(amount.currency.decimals)
}

export const parseAmount = (currency: Currency, rawAmount: bigint) => {
  return CurrencyAmount.fromRawAmount(currency, (rawAmount * 10n ** BigInt(currency.decimals)) / PRECISION)
}

