// a list of tokens by chain
export type ChainMap<T> = {
  readonly [chainId in ChainId]: T
}

export type ChainTokenList = ChainMap<Token[]>

export type BatchMulticallConfig = {
  gasLimitPerCall: number
  dropUnexecutedCalls?: boolean
}

export type BatchMulticallConfigs = {
  defaultConfig: BatchMulticallConfig
  gasErrorFailureOverride: BatchMulticallConfig
  successRateFailureOverrides: BatchMulticallConfig
}

import { ChainId, Currency, CurrencyAmount, Native, Token, WNATIVE } from '@dapp/sdk'

export function wrappedCurrency(currency: Currency | undefined, chainId: ChainId): Token | undefined {
  return currency?.isNative ? WNATIVE[chainId] : currency?.isToken ? currency : undefined
}

export function wrappedCurrencyAmount(
  currencyAmount: CurrencyAmount<Currency> | undefined,
  chainId: ChainId | undefined,
): CurrencyAmount<Token> | undefined {
  const token = currencyAmount && chainId ? wrappedCurrency(currencyAmount.currency, chainId) : undefined
  return token && currencyAmount ? CurrencyAmount.fromRawAmount(token, currencyAmount.quotient) : undefined
}

export function unwrappedToken(token: Currency): Currency {
  if (token.isNative) {
    return token
  }

  if (token.equals(WNATIVE[token.chainId as ChainId])) return Native.onChain(token.chainId)
  return token
}

export type AnyAsyncFunction = (...args: any[]) => Promise<any>

export interface AsyncCall<F extends AnyAsyncFunction> {
  asyncFn: F

  // In millisecond
  timeout?: number
}

function withTimeout<F extends AnyAsyncFunction>(fn: F, duration: number) {
  return function callWithTimeout(...args: Parameters<F>) {
    return Promise.race([
      fn(...args),
      new Promise((_, reject) => {
        setTimeout(() => reject(new Error(`Request timeout ${duration}ms`)), duration)
      }) as ReturnType<F>,
    ])
  }
}

export function withFallback<F extends AnyAsyncFunction>(calls: AsyncCall<F>[]) {
  return async function asyncCall(...args: Parameters<F>) {
    const numOfCalls = calls.length
    if (numOfCalls === 0) {
      throw new Error('No valid calls')
    }
    for (const [index, { timeout = 2000, asyncFn }] of calls.entries()) {
      const fn = index < numOfCalls - 1 ? withTimeout(asyncFn, timeout) : asyncFn
      try {
        // eslint-disable-next-line no-await-in-loop
        const result = await fn(...args)
        return result
      } catch (e) {
        if (index === numOfCalls - 1) {
          throw e
        }
        // Fallback to next one
        console.error('Call failed with error', e, 'Try next fallback')
      }
    }
    throw new Error('Unexpected end of call')
  }
}

export type WithFallbackOptions<F extends AnyAsyncFunction> = {
  // Order matters for fallbacks
  fallbacks?: F[]

  // In millisecond
  fallbackTimeout?: number
}

export function createAsyncCallWithFallbacks<F extends AnyAsyncFunction>(
  defaultCall: F,
  options?: WithFallbackOptions<F>,
) {
  const { fallbacks = [], fallbackTimeout: timeout = 3000 } = options || {}
  return withFallback(
    [defaultCall, ...fallbacks].map((asyncFn) => ({
      asyncFn,
      timeout,
    })),
  )
}

import { BigintIsh, ChainId, Currency, CurrencyAmount } from '@dapp/sdk'
import sum from 'lodash/sum.js'

import {
  BASE_SWAP_COST_STABLE_SWAP,
  BASE_SWAP_COST_V2,
  BASE_SWAP_COST_V3,
  COST_PER_EXTRA_HOP_STABLE_SWAP,
  COST_PER_EXTRA_HOP_V2,
  COST_PER_HOP_V3,
  COST_PER_INIT_TICK,
  COST_PER_UNINIT_TICK,
} from '../constants'
import {
  GasCost,
  GasEstimateRequiredInfo,
  GasModel,
  Pool,
  PoolProvider,
  PoolType,
  RouteWithoutGasEstimate,
} from './types'
import { getNativeWrappedToken, getTokenPrice, getUsdGasToken, isStablePool, isV2Pool, isV3Pool } from './utils'

interface GasModelConfig {
  gasPriceWei: BigintIsh | (() => Promise<BigintIsh>)
  blockNumber?: BigintIsh
  poolProvider: PoolProvider
  quoteCurrency: Currency
}

export async function createGasModel({
  gasPriceWei,
  poolProvider,
  quoteCurrency,
  blockNumber,
}: GasModelConfig): Promise<GasModel> {
  const { chainId } = quoteCurrency
  const usdToken = getUsdGasToken(chainId)
  if (!usdToken) {
    throw new Error(`No valid usd token found on chain ${chainId}`)
  }
  const nativeWrappedToken = getNativeWrappedToken(chainId)
  if (!nativeWrappedToken) {
    throw new Error(`Unsupported chain ${chainId}. Native wrapped token not found.`)
  }

  const gasPrice = BigInt(typeof gasPriceWei === 'function' ? await gasPriceWei() : gasPriceWei)
  const [usdPool, nativePool] = await Promise.all([
    getHighestLiquidityUSDPool(poolProvider, chainId, blockNumber),
    getHighestLiquidityNativePool(poolProvider, quoteCurrency, blockNumber),
  ])

  const estimateGasCost = (
    { pools }: RouteWithoutGasEstimate,
    { initializedTickCrossedList }: GasEstimateRequiredInfo,
  ): GasCost => {
    const isQuoteNative = nativeWrappedToken.equals(quoteCurrency.wrapped)

    const totalInitializedTicksCrossed = BigInt(Math.max(1, sum(initializedTickCrossedList)))
    /**
     * Since we must make a separate call to multicall for each v3 and v2 section, we will have to
     * add the BASE_SWAP_COST to each section.
     */
    const poolTypeSet = new Set<PoolType>()
    let baseGasUse = 0n

    for (const pool of pools) {
      const { type } = pool
      if (isV2Pool(pool)) {
        if (!poolTypeSet.has(type)) {
          baseGasUse += BASE_SWAP_COST_V2
          poolTypeSet.add(type)
          continue
        }
        baseGasUse += COST_PER_EXTRA_HOP_V2
        continue
      }

      if (isV3Pool(pool)) {
        if (!poolTypeSet.has(type)) {
          baseGasUse += BASE_SWAP_COST_V3(chainId)
          poolTypeSet.add(type)
        }
        baseGasUse += COST_PER_HOP_V3(chainId)
        continue
      }

      if (isStablePool(pool)) {
        if (!poolTypeSet.has(type)) {
          baseGasUse += BASE_SWAP_COST_STABLE_SWAP
          poolTypeSet.add(type)
          continue
        }
        baseGasUse += COST_PER_EXTRA_HOP_STABLE_SWAP
        continue
      }
    }

    const tickGasUse = COST_PER_INIT_TICK(chainId) * totalInitializedTicksCrossed
    const uninitializedTickGasUse = COST_PER_UNINIT_TICK * 0n

    // base estimate gas used based on chainId estimates for hops and ticks gas useage
    baseGasUse = baseGasUse + tickGasUse + uninitializedTickGasUse

    const baseGasCostWei = gasPrice * baseGasUse

    const totalGasCostNativeCurrency = CurrencyAmount.fromRawAmount(nativeWrappedToken, baseGasCostWei)

    let gasCostInToken: CurrencyAmount<Currency> = CurrencyAmount.fromRawAmount(quoteCurrency.wrapped, 0)
    let gasCostInUSD: CurrencyAmount<Currency> = CurrencyAmount.fromRawAmount(usdToken, 0)

    try {
      if (isQuoteNative) {
        gasCostInToken = totalGasCostNativeCurrency
      }
      if (!isQuoteNative && nativePool) {
        const price = getTokenPrice(nativePool, nativeWrappedToken, quoteCurrency.wrapped)
        gasCostInToken = price.quote(totalGasCostNativeCurrency)
      }

      if (usdPool) {
        const nativeTokenUsdPrice = getTokenPrice(usdPool, nativeWrappedToken, usdToken)
        gasCostInUSD = nativeTokenUsdPrice.quote(totalGasCostNativeCurrency)
      }
    } catch (e) {
      // console.warn('Cannot estimate gas cost', e)
    }
    return {
      gasEstimate: baseGasUse,
      gasCostInToken,
      gasCostInUSD,
    }
  }

  return {
    estimateGasCost,
  }
}

async function getHighestLiquidityNativePool(
  poolProvider: PoolProvider,
  currency: Currency,
  blockNumber?: BigintIsh,
): Promise<Pool | null> {
  const nativeWrappedToken = getNativeWrappedToken(currency.chainId)
  if (!nativeWrappedToken || currency.wrapped.equals(nativeWrappedToken)) {
    return null
  }

  const pools = await poolProvider.getCandidatePools({
    blockNumber,
    pairs: [[nativeWrappedToken, currency]],
    currencyA: nativeWrappedToken,
    currencyB: currency,
  })
  // TODO get the first pool we have for now
  return pools[0] ?? null
}

async function getHighestLiquidityUSDPool(
  poolProvider: PoolProvider,
  chainId: ChainId,
  blockNumber?: BigintIsh,
): Promise<Pool | null> {
  const usdToken = getUsdGasToken(chainId)
  const nativeWrappedToken = getNativeWrappedToken(chainId)
  if (!usdToken || !nativeWrappedToken) {
    return null
  }
  const pools = await poolProvider.getCandidatePools({
    blockNumber,
    pairs: [[nativeWrappedToken, usdToken]],
    currencyA: nativeWrappedToken,
    currencyB: usdToken,
  })
  // TODO get the first pool we have for now
  return pools[0] ?? null
}

import { BigintIsh, ChainId, Currency, CurrencyAmount, TradeType, ZERO } from '@dapp/sdk'

import { computeAllRoutes, getBestRouteCombinationByQuotes } from './functions'
import { createGasModel } from './gasModel'
import { getRoutesWithValidQuote } from './getRoutesWithValidQuote'
import { BestRoutes, TradeConfig, RouteConfig, SmartRouterTrade, RouteType } from './types'
import { ROUTE_CONFIG_BY_CHAIN } from './constants'

export async function getBestTrade(
  amount: CurrencyAmount<Currency>,
  currency: Currency,
  tradeType: TradeType,
  config: TradeConfig,
): Promise<SmartRouterTrade<TradeType> | null> {
  const { blockNumber: blockNumberFromConfig } = config
  const blockNumber: BigintIsh | undefined =
    typeof blockNumberFromConfig === 'function' ? await blockNumberFromConfig() : blockNumberFromConfig
  const bestRoutes = await getBestRoutes(amount, currency, tradeType, {
    ...config,
    blockNumber,
  })
  if (!bestRoutes || bestRoutes.outputAmount.equalTo(ZERO)) {
    throw new Error('Cannot find a valid swap route')
  }

  const { routes, gasEstimateInUSD, gasEstimate, inputAmount, outputAmount } = bestRoutes
  // TODO restrict trade type to exact input if routes include one of the old
  // stable swap pools, which only allow to swap with exact input
  return {
    tradeType,
    routes,
    gasEstimate,
    gasEstimateInUSD,
    inputAmount,
    outputAmount,
    blockNumber,
  }
}

async function getBestRoutes(
  amount: CurrencyAmount<Currency>,
  currency: Currency,
  tradeType: TradeType,
  routeConfig: RouteConfig,
): Promise<BestRoutes | null> {
  const { chainId } = currency
  const {
    maxHops = 3,
    maxSplits = 4,
    distributionPercent = 5,
    poolProvider,
    quoteProvider,
    blockNumber,
    gasPriceWei,
    allowedPoolTypes,
    quoterOptimization,
  } = {
    ...routeConfig,
    ...(ROUTE_CONFIG_BY_CHAIN[chainId as ChainId] || {}),
  }
  const isExactIn = tradeType === TradeType.EXACT_INPUT
  const inputCurrency = isExactIn ? amount.currency : currency
  const outputCurrency = isExactIn ? currency : amount.currency

  const candidatePools = await poolProvider?.getCandidatePools({
    currencyA: amount.currency,
    currencyB: currency,
    blockNumber,
    protocols: allowedPoolTypes,
  })

  let baseRoutes = computeAllRoutes(inputCurrency, outputCurrency, candidatePools, maxHops)
  // Do not support mix route on exact output
  if (tradeType === TradeType.EXACT_OUTPUT) {
    baseRoutes = baseRoutes.filter(({ type }) => type !== RouteType.MIXED)
  }

  const gasModel = await createGasModel({ gasPriceWei, poolProvider, quoteCurrency: currency, blockNumber })
  const routesWithValidQuote = await getRoutesWithValidQuote({
    amount,
    baseRoutes,
    distributionPercent,
    quoteProvider,
    tradeType,
    blockNumber,
    gasModel,
    quoterOptimization,
  })
  // routesWithValidQuote.forEach(({ percent, path, amount: a, quote }) => {
  //   const pathStr = path.map((t) => t.symbol).join('->')
  //   console.log(
  //     `${percent}% Swap`,
  //     a.toExact(),
  //     a.currency.symbol,
  //     'through',
  //     pathStr,
  //     ':',
  //     quote.toExact(),
  //     quote.currency.symbol,
  //   )
  // })
  return getBestRouteCombinationByQuotes(amount, currency, routesWithValidQuote, tradeType, { maxSplits })
}

/* eslint-disable no-console */
import { BigintIsh, Currency, CurrencyAmount, TradeType } from '@dapp/sdk'
import chunk from 'lodash/chunk.js'

import { BaseRoute, GasModel, QuoteProvider, RouteWithoutQuote, RouteWithQuote } from './types'
import { getAmountDistribution } from './functions'
import { metric } from './utils/metric'

interface Params {
  blockNumber?: BigintIsh
  amount: CurrencyAmount<Currency>
  baseRoutes: BaseRoute[]
  distributionPercent: number
  quoteProvider: QuoteProvider
  tradeType: TradeType
  gasModel: GasModel
  quoterOptimization?: boolean
}

export async function getRoutesWithValidQuote({
  amount,
  baseRoutes,
  distributionPercent,
  quoteProvider,
  tradeType,
  blockNumber,
  gasModel,
  quoterOptimization = true,
}: Params): Promise<RouteWithQuote[]> {
  const [percents, amounts] = getAmountDistribution(amount, distributionPercent)
  const routesWithoutQuote = amounts.reduce<RouteWithoutQuote[]>(
    (acc, curAmount, i) => [
      ...acc,
      ...baseRoutes.map((r) => ({
        ...r,
        amount: curAmount,
        percent: percents[i],
      })),
    ],
    [],
  )
  const getRoutesWithQuote =
    tradeType === TradeType.EXACT_INPUT
      ? quoteProvider.getRouteWithQuotesExactIn
      : quoteProvider.getRouteWithQuotesExactOut

  if (!quoterOptimization) {
    return getRoutesWithQuote(routesWithoutQuote, { blockNumber, gasModel })
  }

  const requestCallback = typeof window === 'undefined' ? setTimeout : window.requestIdleCallback || window.setTimeout
  metric('Get quotes', 'from', routesWithoutQuote.length, 'routes', routesWithoutQuote)
  // Split into chunks so the calculation won't block the main thread
  const getQuotes = (routes: RouteWithoutQuote[]): Promise<RouteWithQuote[]> =>
    new Promise((resolve, reject) => {
      requestCallback(async () => {
        try {
          const result = await getRoutesWithQuote(routes, { blockNumber, gasModel })
          resolve(result)
        } catch (e) {
          reject(e)
        }
      })
    })
  const chunks = chunk(routesWithoutQuote, 10)
  const result = await Promise.all(chunks.map(getQuotes))
  const quotes = result.reduce<RouteWithQuote[]>((acc, cur) => [...acc, ...cur], [])
  metric('Get quotes', 'success, got', quotes.length, 'quoted routes', quotes)
  return quotes
}

import { ChainId, Currency, CurrencyAmount, Pair, Token } from '@dapp/sdk'
import { Address } from 'viem'

import { wrappedCurrency } from '../../evm/utils/currency'
import { pancakePairABI } from '../../evm/abis/IPancakePair'

import { Provider } from '../types'

type CurrencyPair = [Currency, Currency]

export enum PairState {
  LOADING,
  NOT_EXISTS,
  EXISTS,
  INVALID,
}

interface Options {
  provider: Provider
  chainId: ChainId
}

export async function getPairs(currencyPairs: CurrencyPair[], { provider, chainId }: Options): Promise<Pair[]> {
  const tokens: [Token | undefined, Token | undefined][] = currencyPairs.map(([currencyA, currencyB]) => [
    wrappedCurrency(currencyA, chainId),
    wrappedCurrency(currencyB, chainId),
  ])

  const pairAddresses = tokens.map(getPairAddress)

  const client = provider({ chainId })

  const results = await client.multicall({
    contracts: pairAddresses.map(
      (address) =>
      ({
        abi: pancakePairABI,
        address,
        functionName: 'getReserves',
      } as const),
    ),
    allowFailure: true,
  })

  const resultWithState: [PairState, Pair | null][] = results.map((result, i) => {
    if (!result || result.status !== 'success') return [PairState.NOT_EXISTS, null]

    const tokenA = tokens[i][0]
    const tokenB = tokens[i][1]

    if (!tokenA || !tokenB || tokenA.equals(tokenB)) return [PairState.INVALID, null]

    const [token0, token1] = tokenA.sortsBefore(tokenB) ? [tokenA, tokenB] : [tokenB, tokenA]

    const [reserve0, reserve1] = result.result
    return [
      PairState.EXISTS,
      new Pair(CurrencyAmount.fromRawAmount(token0, reserve0), CurrencyAmount.fromRawAmount(token1, reserve1)),
    ]
  })
  const successfulResult: [PairState.EXISTS, Pair][] = resultWithState.filter(
    (result): result is [PairState.EXISTS, Pair] => Boolean(result[0] === PairState.EXISTS && result[1]),
  )
  return successfulResult.map(([, pair]) => pair)
}

function getPairAddress([tokenA, tokenB]: [Token | undefined, Token | undefined]): Address {
  let addr: Address = '0x'
  try {
    addr = tokenA && tokenB && !tokenA.equals(tokenB) ? Pair.getAddress(tokenA, tokenB) : '0x'
  } catch (error: any) {
    // Debug Invariant failed related to this line
    console.error(error.msg, `- pairAddresses: ${tokenA?.address}-${tokenB?.address}`, `chainId: ${tokenA?.chainId}`)
  }
  return addr
}

import { ChainId, Currency, CurrencyAmount } from '@dapp/sdk'

import { wrappedCurrencyAmount } from '../../evm/utils/currency'
import { getOutputToken } from '../utils/pair'
import { StableSwapPair, Provider, StableSwapFeeRaw } from '../types'
import { STABLE_SWAP_INFO_ADDRESS } from '../../evm/constants'
import { infoStableSwapABI } from '../../evm/abis/InfoStableSwap'

export function getStableSwapFeeCall(pair: StableSwapPair, inputAmount: CurrencyAmount<Currency>) {
  const { chainId } = inputAmount.currency
  const wrappedInputAmount = wrappedCurrencyAmount(inputAmount, chainId)
  if (!wrappedInputAmount) {
    throw new Error(`No wrapped token amount found for input amount: ${inputAmount.currency.name}`)
  }

  const { stableSwapAddress } = pair
  const inputToken = wrappedInputAmount.currency
  const outputToken = getOutputToken(pair, inputToken)
  const inputRawAmount = inputAmount.wrapped.quotient

  const isOutputToken0 = pair.token0.equals(outputToken)
  const args = isOutputToken0
    ? ([stableSwapAddress, 1n, 0n, inputRawAmount] as const)
    : ([stableSwapAddress, 0n, 1n, inputRawAmount] as const)
  return {
    abi: infoStableSwapABI,
    address: pair.infoStableSwapAddress || STABLE_SWAP_INFO_ADDRESS[chainId as ChainId],
    functionName: 'get_exchange_fee',
    args,
  } as const
}

interface Options {
  provider: Provider
}

export async function getStableSwapFee(
  pair: StableSwapPair,
  inputAmount: CurrencyAmount<Currency>,
  { provider }: Options,
): Promise<StableSwapFeeRaw> {
  // eslint-disable-next-line prefer-destructuring
  const chainId: ChainId = inputAmount.currency.chainId
  const call = getStableSwapFeeCall(pair, inputAmount)
  const outputToken = getOutputToken(pair, inputAmount.currency)

  const client = provider({ chainId })

  const [[feeRaw, adminFeeRaw]] = await client.multicall({
    contracts: [call],
    allowFailure: false,
  })

  return {
    fee: CurrencyAmount.fromRawAmount(outputToken, feeRaw),
    adminFee: CurrencyAmount.fromRawAmount(outputToken, adminFeeRaw),
  }
}

