import { Currency } from '@dapp/sdk'

import { Pair, StableSwapPair } from '../types'

export function involvesToken(pair: Pair, token: Currency) {
  const { token0, token1 } = pair
  return token0.wrapped.equals(token.wrapped) || token1.wrapped.equals(token.wrapped)
}

export function includesPair(pairs: Pair[], pair: Pair) {
  return pairs.some((p) => isSamePair(p, pair))
}

export function isSamePair(one: Pair, another: Pair) {
  return involvesToken(another, one.token0) && involvesToken(another, one.token1)
}

export function getOutputToken(pair: Pair, inputToken: Currency) {
  return inputToken.wrapped.equals(pair.token0.wrapped) ? pair.token1 : pair.token0
}

export function isStableSwapPair(pair: Pair): pair is StableSwapPair {
  return !!(pair as StableSwapPair).stableSwapAddress
}

import { Currency, Price } from '@dapp/sdk'

import { RouteWithStableSwap } from '../types'
import { isStableSwapPair } from './pair'

export function getMidPrice<TIn extends Currency, TOut extends Currency>(
  route: RouteWithStableSwap<TIn, TOut>,
): Price<TIn, TOut> {
  // TODO caching
  const prices: Price<Currency, Currency>[] = []
  for (const [i, pair] of route.pairs.entries()) {
    if (isStableSwapPair(pair)) {
      prices.push(route.path[i].wrapped.equals(pair.price.baseCurrency.wrapped) ? pair.price : pair.price.invert())
      // eslint-disable-next-line no-continue
      continue
    }
    prices.push(
      route.path[i].wrapped.equals(pair.token0.wrapped)
        ? new Price(pair.reserve0.currency, pair.reserve1.currency, pair.reserve0.quotient, pair.reserve1.quotient)
        : new Price(pair.reserve1.currency, pair.reserve0.currency, pair.reserve1.quotient, pair.reserve0.quotient),
    )
  }
  const reduced = prices.slice(1).reduce((accumulator, currentValue) => accumulator.multiply(currentValue), prices[0])
  return new Price(route.input, route.output, reduced.denominator, reduced.numerator)
}

